// dropos-backend-build.js
const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"backend/prisma/schema.prisma":"// prisma/schema.prisma\n// DropOS - Full Multi-Tenant SaaS Schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Enums ───────────────────────────────────────────────────────────────────\n\nenum Role {\n  SUPER_ADMIN\n  STORE_OWNER\n  CUSTOMER\n}\n\nenum UserStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING_VERIFICATION\n  BANNED\n}\n\nenum PlanType {\n  STARTER\n  PRO\n  ADVANCED\n}\n\nenum StoreStatus {\n  ACTIVE\n  SUSPENDED\n  PENDING\n  ARCHIVED\n}\n\nenum ProductStatus {\n  ACTIVE\n  DRAFT\n  OUT_OF_STOCK\n  ARCHIVED\n}\n\nenum OrderStatus {\n  PENDING\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  COMPLETED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  REFUNDED\n  DISPUTED\n}\n\nenum PaymentGateway {\n  STRIPE\n  PAYSTACK\n  FLUTTERWAVE\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  CANCELLED\n  EXPIRED\n  PAST_DUE\n}\n\nenum SupportStatus {\n  OPEN\n  IN_PROGRESS\n  RESOLVED\n  CLOSED\n}\n\nenum Priority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\nenum LogLevel {\n  INFO\n  WARN\n  ERROR\n  CRITICAL\n}\n\n// ─── User ────────────────────────────────────────────────────────────────────\n\nmodel User {\n  id                String     @id @default(uuid())\n  email             String     @unique\n  password          String\n  name              String\n  phone             String?\n  avatar            String?\n  role              Role       @default(STORE_OWNER)\n  status            UserStatus @default(PENDING_VERIFICATION)\n  emailVerified     Boolean    @default(false)\n  emailVerifyToken  String?\n  passwordResetToken String?\n  passwordResetExpiry DateTime?\n  twoFAEnabled      Boolean    @default(false)\n  twoFASecret       String?\n  lastLogin         DateTime?\n  loginAttempts     Int        @default(0)\n  lockedUntil       DateTime?\n  refreshToken      String?\n  adminNotes        String?\n  flags             String[]   @default([])\n  onboarded         Boolean    @default(false)\n  onboardNiche      String?\n  onboardStage      String?\n  onboardGoal       String?\n  onboardTemplate   String?\n  country           String?\n  city              String?\n  timezone          String?    @default(\"UTC\")\n  createdAt         DateTime   @default(now())\n  updatedAt         DateTime   @updatedAt\n\n  // Relations\n  stores            Store[]\n  kaiConversations  KaiConversation[]\n  subscription      Subscription?\n  supportTickets    SupportTicket[]\n  notifications     Notification[]\n  auditLogs         AuditLog[]\n  pushSubscriptions PushSubscription[]\n  referral          Referral?\n\n  @@index([email])\n  @@index([role])\n  @@index([status])\n  @@map(\"users\")\n}\n\n// ─── Store ───────────────────────────────────────────────────────────────────\n\nmodel Store {\n  id              String      @id @default(uuid())\n  ownerId         String\n  name            String\n  slug            String      @unique\n  description     String?\n  logo            String?\n  banner          String?\n  domain          String?     @unique\n  customDomain    String?     @unique\n  templateId      String?\n  paystackConnected Boolean  @default(false)\n  status          StoreStatus @default(PENDING)\n  primaryColor    String?     @default(\"#7c3aed\")\n  accentColor     String?     @default(\"#a855f7\")\n  theme           String?     @default(\"default\")\n  secondaryColor  String?\n  fontFamily      String?     @default(\"DM Sans\")\n  borderRadius    String?     @default(\"rounded\")\n  tagline         String?\n  showReviews     Boolean     @default(true)\n  showInventory   Boolean     @default(true)\n  productsPerRow  Int         @default(4)\n  currency        String      @default(\"USD\")\n  country         String?\n  address         String?\n  supportEmail    String?\n  supportPhone    String?\n  taxRate         Float?      @default(0)\n  shippingEnabled Boolean     @default(true)\n  freeShippingMin Float?\n  metaTitle         String?\n  metaDescription   String?\n  // ── SMS / WhatsApp via Twilio ─────────────────────────────────────────────\n  suppliers           Supplier[]\n  fulfillmentOrders   FulfillmentOrder[]\n\n  // ── Multi-currency ───────────────────────────────────────────────────────────\n  supportedCurrencies Json?       // e.g. [\"USD\",\"EUR\",\"GBP\",\"NGN\"]\n  autoDetectCurrency  Boolean     @default(true)\n  smsEnabled        Boolean     @default(false)\n  smsPhone          String?     // owner's phone for incoming alerts  e.g. +2348012345678\n  whatsappEnabled   Boolean     @default(false)\n  whatsappPhone     String?     // owner's WhatsApp number\n  // ── Live Chat widget ────────────────────────────────────────────────────────\n  liveChatProvider  String?     // \"tawk\", \"crisp\", \"tidio\", \"whatsapp\", or null\n  liveChatId        String?     // Tawk.to property ID / Crisp website ID / Tidio key\n  liveChatEnabled   Boolean     @default(false)\n  notifyOwnerSms    Boolean     @default(true)   // SMS owner on new order\n  notifyCustomerSms Boolean     @default(false)  // SMS customer on order + status\n  createdAt         DateTime    @default(now())\n  updatedAt       DateTime    @updatedAt\n\n  // Relations\n  owner           User        @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  products        Product[]\n  orders          Order[]\n  customers       StoreCustomer[]\n  payments        Payment[]\n  analytics       Analytics[]\n  shippingZones   ShippingZone[]\n  coupons         Coupon[]\n  reviews         Review[]\n  abandonedCarts  AbandonedCart[]\n\n  discounts       Discount[]\n  refunds         Refund[]\n  giftCards       GiftCard[]\n  webhooks        StoreWebhook[]\n  flashSales      FlashSale[]\n  backups         StoreBackup[]\n  apiKeys         ApiKey[]\n  returnRequests  ReturnRequest[]\n  affiliates      Affiliate[]\n  @@index([ownerId])\n  @@index([slug])\n  @@index([status])\n  @@map(\"stores\")\n  integrations    StoreIntegration[]\n}\n\n// ─── Product ─────────────────────────────────────────────────────────────────\n\nmodel Product {\n  id              String        @id @default(uuid())\n  storeId         String\n  name            String\n  slug            String\n  description     String?\n  price           Float\n  comparePrice    Float?\n  costPrice       Float?\n  sku             String?\n  barcode         String?\n  weight          Float?\n  inventory       Int           @default(0)\n  trackInventory  Boolean       @default(true)\n  allowBackorder  Boolean       @default(false)\n  images          String[]      @default([])\n  category        String?\n  tags            String[]      @default([])\n  status          ProductStatus @default(DRAFT)\n  isDigital       Boolean       @default(false)\n  metaTitle       String?\n  metaDescription String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  // Relations\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  variants        ProductVariant[]\n  orderItems      OrderItem[]\n  reviews         Review[]\n  supplierProducts SupplierProduct[]\n\n  @@unique([storeId, slug])\n  @@index([storeId])\n  @@index([status])\n  @@map(\"products\")\n}\n\nmodel ProductVariant {\n  id          String   @id @default(uuid())\n  productId   String\n  name        String\n  value       String\n  price       Float?\n  inventory   Int      @default(0)\n  sku         String?\n  image       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@map(\"product_variants\")\n}\n\n// ─── Store Customer ──────────────────────────────────────────────────────────\n\nmodel StoreCustomer {\n  id              String    @id @default(uuid())\n  storeId         String\n  email           String\n  name            String\n  phone           String?\n  address         Json?\n  emailVerified   Boolean   @default(false)\n  totalSpent      Float     @default(0)\n  orderCount      Int       @default(0)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  store           Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  orders          Order[]\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"store_customers\")\n}\n\n// ─── Order ───────────────────────────────────────────────────────────────────\n\nmodel Order {\n  id                String      @id @default(uuid())\n  orderNumber       String      @unique\n  storeId           String\n  customerId        String?\n  customerEmail     String\n  customerName      String\n  customerPhone     String?\n  shippingAddress   Json?\n  billingAddress    Json?\n  status            OrderStatus @default(PENDING)\n  subtotal          Float\n  shippingCost      Float       @default(0)\n  taxAmount         Float       @default(0)\n  discountAmount    Float       @default(0)\n  total             Float\n  currency          String      @default(\"USD\")\n  notes             String?\n  trackingNumber    String?\n  trackingUrl       String?\n  refundAmount      Float?\n  cancelReason      String?\n  createdAt         DateTime    @default(now())\n  updatedAt         DateTime    @updatedAt\n\n  store             Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  customer          StoreCustomer? @relation(fields: [customerId], references: [id])\n  items             OrderItem[]\n  payment           Payment?\n  refunds           Refund[]\n  returns           ReturnRequest[]\n\n  @@index([storeId])\n  @@index([status])\n  @@index([orderNumber])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id          String   @id @default(uuid())\n  orderId     String\n  productId   String\n  variantId   String?\n  name        String\n  sku         String?\n  price       Float\n  quantity    Int\n  total       Float\n  image       String?\n  createdAt   DateTime @default(now())\n\n  order       Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product     Product  @relation(fields: [productId], references: [id])\n\n  @@index([orderId])\n  @@map(\"order_items\")\n}\n\n// ─── Payment ─────────────────────────────────────────────────────────────────\n\nmodel Payment {\n  id                String         @id @default(uuid())\n  orderId           String         @unique\n  storeId           String\n  gateway           PaymentGateway\n  gatewayReference  String?\n  gatewayResponse   Json?\n  amount            Float\n  currency          String         @default(\"USD\")\n  platformFee       Float\n  platformFeePercent Float\n  storeEarnings     Float\n  status            PaymentStatus  @default(PENDING)\n  paidAt            DateTime?\n  refundedAt        DateTime?\n  metadata          Json?\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n\n  order             Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store             Store          @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([status])\n  @@index([gateway])\n  @@map(\"payments\")\n}\n\n// ─── Subscription ────────────────────────────────────────────────────────────\n\nmodel Subscription {\n  id                  String             @id @default(uuid())\n  userId              String             @unique\n  plan                PlanType           @default(STARTER)\n  status              SubscriptionStatus @default(ACTIVE)\n  currentPeriodStart  DateTime\n  currentPeriodEnd    DateTime\n  cancelAtPeriodEnd   Boolean            @default(false)\n  stripeSubId         String?\n  paystackSubCode     String?\n  price               Float\n  currency            String             @default(\"USD\")\n  createdAt           DateTime           @default(now())\n  updatedAt           DateTime           @updatedAt\n\n  user                User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"subscriptions\")\n}\n\n// ─── Analytics ───────────────────────────────────────────────────────────────\n\nmodel Analytics {\n  id            String   @id @default(uuid())\n  storeId       String\n  date          DateTime @db.Date\n  views         Int      @default(0)\n  visitors      Int      @default(0)\n  orders        Int      @default(0)\n  revenue       Float    @default(0)\n  conversions   Float    @default(0)\n  avgOrderValue Float    @default(0)\n  newCustomers  Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, date])\n  @@index([storeId])\n  @@map(\"analytics\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\n\n// ─── Support Ticket ──────────────────────────────────────────────────────────\n\nmodel SupportTicket {\n  id          String        @id @default(uuid())\n  userId      String\n  subject     String\n  message     String\n  status      SupportStatus @default(OPEN)\n  priority    Priority      @default(MEDIUM)\n  adminReply  String?\n  resolvedAt  DateTime?\n  createdAt   DateTime      @default(now())\n  updatedAt   DateTime      @updatedAt\n\n  user        User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  replies     TicketReply[]\n\n  @@index([userId])\n  @@index([status])\n  @@map(\"support_tickets\")\n}\n\nmodel TicketReply {\n  id        String        @id @default(uuid())\n  ticketId  String\n  senderId  String\n  isAdmin   Boolean       @default(false)\n  message   String\n  createdAt DateTime      @default(now())\n\n  ticket    SupportTicket @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n\n  @@index([ticketId])\n  @@map(\"ticket_replies\")\n}\n\n// ─── Platform Settings ───────────────────────────────────────────────────────\n\nmodel PlatformSettings {\n  id                  String   @id @default(\"singleton\")\n  platformFeePercent  Float    @default(10)\n  starterPrice        Float    @default(9)\n  proPrice            Float    @default(29)\n  advancedPrice       Float    @default(79)\n  maintenanceMode     Boolean  @default(false)\n  allowRegistration   Boolean  @default(true)\n  maxStoresPerOwner   Json     @default(\"{\\\"STARTER\\\":1,\\\"PRO\\\":3,\\\"ADVANCED\\\":999}\")\n  maxProductsPerStore Json     @default(\"{\\\"STARTER\\\":50,\\\"PRO\\\":500,\\\"ADVANCED\\\":999999}\")\n  smtpConfig          Json?\n  updatedAt           DateTime @updatedAt\n\n  @@map(\"platform_settings\")\n}\n\n// ─── Notification ────────────────────────────────────────────────────────────\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  title     String\n  message   String\n  type      String   @default(\"info\")\n  read      Boolean  @default(false)\n  link      String?\n  createdAt DateTime @default(now())\n\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([read])\n  @@map(\"notifications\")\n}\n\n// ─── Audit Log ───────────────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id          String   @id @default(uuid())\n  userId      String?\n  action      String\n  entity      String\n  entityId    String?\n  oldValues   Json?\n  newValues   Json?\n  ipAddress   String?\n  userAgent   String?\n  level       LogLevel @default(INFO)\n  createdAt   DateTime @default(now())\n\n  user        User?    @relation(fields: [userId], references: [id])\n\n  @@index([userId])\n  @@index([entity])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n\n// ─── Error Log ───────────────────────────────────────────────────────────────\n\nmodel ErrorLog {\n  id          String   @id @default(uuid())\n  message     String\n  stack       String?\n  path        String?\n  method      String?\n  statusCode  Int?\n  userId      String?\n  ipAddress   String?\n  resolved    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([resolved])\n  @@index([createdAt])\n  @@map(\"error_logs\")\n}\n\n// ─── Coupon ──────────────────────────────────────────────────────────────────\n\nmodel Coupon {\n  id            String    @id @default(uuid())\n  storeId       String\n  code          String\n  type          String    // PERCENTAGE | FIXED\n  value         Float\n  minOrderValue Float     @default(0)\n  maxUses       Int?\n  usedCount     Int       @default(0)\n  isActive      Boolean   @default(true)\n  expiresAt     DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  store         Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"coupons\")\n}\n\n// ─── Shipping Zone ───────────────────────────────────────────────────────────\n\nmodel ShippingZone {\n  id            String   @id @default(uuid())\n  storeId       String\n  name          String\n  countries     String[]\n  shippingRate  Float    @default(0)\n  freeThreshold Float?\n  estimatedDays String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"shipping_zones\")\n}\n\n// ─── Review ──────────────────────────────────────────────────────────────────\n\nmodel Review {\n  id         String   @id @default(uuid())\n  storeId    String\n  productId  String\n  name       String\n  email      String\n  rating     Int      // 1-5\n  title      String?\n  body       String\n  photos     String[] // array of image URLs\n  approved   Boolean  @default(false)\n  featured   Boolean  @default(false)\n  helpful    Int      @default(0)\n  verified   Boolean  @default(false)\n  orderId    String?  // set if from verified purchase\n  replyBody  String?  // store owner reply\n  repliedAt  DateTime?\n  source     String?  // \"email\" | \"in-app\" | \"import\"\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  store   Store   @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId])\n  @@index([storeId])\n  @@map(\"reviews\")\n}\n\n// ─── Abandoned Cart ───────────────────────────────────────────────────────────\n\nmodel AbandonedCart {\n  id            String   @id @default(uuid())\n  storeId       String\n  email         String\n  name          String?\n  items         Json     // CartItem[]\n  total         Float\n  currency      String   @default(\"USD\")\n  token         String   @unique @default(uuid())  // recovery link token\n  recovered     Boolean  @default(false)\n  emailSent     Boolean  @default(false)\n  emailSentAt   DateTime?\n  recoveredAt   DateTime?\n  reminderCount Int      @default(0)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  store         Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([email])\n  @@index([token])\n  @@index([recovered, emailSent])\n  @@map(\"abandoned_carts\")\n}\n\n// ─── Supplier ─────────────────────────────────────────────────────────────────\n\nmodel Supplier {\n  id           String       @id @default(uuid())\n  storeId      String\n  name         String\n  type         SupplierType @default(MANUAL)\n  websiteUrl   String?\n  apiKey       String?\n  apiSecret    String?\n  contactEmail String?\n  contactName  String?\n  notes        String?\n  isActive     Boolean      @default(true)\n  autoFulfill  Boolean      @default(false)  // auto-forward orders when PROCESSING\n  fulfillEmail String?                        // email to send order details to\n  webhookUrl   String?                        // POST order JSON here on new order\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  store            Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  products         SupplierProduct[]\n  fulfillmentOrders FulfillmentOrder[]\n\n  @@index([storeId])\n  @@map(\"suppliers\")\n}\n\nmodel SupplierProduct {\n  id              String   @id @default(uuid())\n  supplierId      String\n  productId       String\n  supplierSku     String?             // SKU in supplier's system\n  supplierUrl     String?             // original product URL (e.g. AliExpress)\n  supplierPrice   Float?              // cost from supplier (in supplier's currency)\n  supplierCurrency String  @default(\"USD\")\n  processingDays  Int?                // how many days to process\n  shippingDays    Int?                // estimated shipping\n  lastSynced      DateTime?\n  stockStatus     String?             // \"IN_STOCK\" | \"LOW_STOCK\" | \"OUT_OF_STOCK\"\n  priority        Int      @default(1)  // 1 = primary, higher = fallback\n  isActive        Boolean  @default(true)\n  notes           String?             // internal notes\n  createdAt       DateTime @default(now())\n\n  supplier  Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([supplierId, productId])\n  @@index([productId])\n  @@map(\"supplier_products\")\n}\n\nmodel FulfillmentOrder {\n  id          String            @id @default(uuid())\n  orderId     String\n  supplierId  String\n  storeId     String\n  status      FulfillmentStatus @default(PENDING)\n  sentAt      DateTime?\n  confirmedAt DateTime?\n  notes       String?\n  supplierRef String?           // reference/tracking from supplier\n  method      String?           // \"EMAIL\" | \"WEBHOOK\" | \"MANUAL\"\n  payload     Json?             // what was sent to supplier\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  supplier Supplier @relation(fields: [supplierId], references: [id])\n  store    Store    @relation(fields: [storeId],    references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([supplierId])\n  @@index([storeId])\n  @@map(\"fulfillment_orders\")\n}\n\n\nenum SupplierType {\n  MANUAL\n  ALIEXPRESS\n  CSV\n  WEBHOOK\n}\n\nenum FulfillmentStatus {\n  PENDING\n  SENT\n  CONFIRMED\n  SHIPPED\n  FAILED\n}\n\n\n// ─── Discount Engine ─────────────────────────────────────────────────────────\n\nmodel Discount {\n  id          String       @id @default(uuid())\n  storeId     String\n  name        String\n  description String?\n  type        DiscountType\n  status      DiscountStatus @default(ACTIVE)\n  priority    Int          @default(0)   // higher = applied first\n  stackable   Boolean      @default(false)\n\n  // Trigger conditions\n  minOrderValue    Float?\n  minQuantity      Int?\n  customerTag      String?  // e.g. \"VIP\", \"wholesale\"\n  productIds       String[] // empty = all products\n  collectionIds    String[]\n  firstOrderOnly   Boolean  @default(false)\n\n  // Value / Action\n  valueType   DiscountValueType\n  value       Float             // %, fixed $, or new price\n  maxDiscount Float?            // cap on percentage discounts\n  freeShipping Boolean          @default(false)\n\n  // BOGO fields\n  bogoRequiredQty  Int?         // buy X\n  bogoGetQty       Int?         // get Y\n  bogoPctOff       Float?       // discount on the free item (100 = fully free)\n\n  // Tiered pricing (JSON array of {qty, pct})\n  tiers       Json?            // [{minQty:2,discount:10},{minQty:5,discount:20}]\n\n  // Flash sale\n  flashSaleEndsAt DateTime?\n  flashSaleStartsAt DateTime?\n\n  // Usage limits\n  maxUses       Int?\n  maxUsesPerCustomer Int?\n  usedCount     Int       @default(0)\n\n  // Validity\n  startsAt   DateTime?\n  expiresAt  DateTime?\n  isAutomatic Boolean   @default(false) // no code needed\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store  Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  usages DiscountUsage[]\n\n  @@index([storeId])\n  @@map(\"discounts\")\n}\n\nmodel DiscountUsage {\n  id          String   @id @default(uuid())\n  discountId  String\n  orderId     String\n  customerId  String?\n  amountSaved Float\n  appliedAt   DateTime @default(now())\n\n  discount Discount @relation(fields: [discountId], references: [id], onDelete: Cascade)\n\n  @@index([discountId])\n  @@index([orderId])\n  @@map(\"discount_usages\")\n}\n\nenum DiscountType {\n  AUTOMATIC     // applies automatically at checkout\n  BOGO          // buy X get Y\n  TIERED        // volume tiers\n  FLASH_SALE    // time-limited\n  PERCENTAGE    // classic % off\n  FIXED         // fixed $ off\n  FREE_SHIPPING // free shipping\n  BUNDLE        // spend X get Y\n}\n\nenum DiscountStatus {\n  ACTIVE\n  PAUSED\n  EXPIRED\n  SCHEDULED\n}\n\nenum DiscountValueType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  NEW_PRICE\n  FREE\n}\n\n// ─── Referral & Affiliate System ─────────────────────────────────────────────\n\nmodel Affiliate {\n  id          String          @id @default(uuid())\n  storeId     String\n  name        String\n  email       String\n  code        String          // unique referral code\n  status      AffiliateStatus @default(PENDING)\n  commissionPct Float         @default(10)  // % of order value\n  commissionFlat Float?       // flat $ per sale (override)\n  payoutMethod  String?       // \"paypal\" | \"bank\" | \"store_credit\"\n  payoutDetails Json?         // encrypted payout info\n  totalEarned   Float         @default(0)\n  totalPaid     Float         @default(0)\n  totalClicks   Int           @default(0)\n  totalOrders   Int           @default(0)\n  notes         String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  store     Store             @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  referrals ReferralConversion[]\n  payouts   AffiliatePayout[]\n\n  @@unique([storeId, code])\n  @@index([storeId])\n  @@map(\"affiliates\")\n}\n\nmodel ReferralConversion {\n  id          String   @id @default(uuid())\n  affiliateId String\n  orderId     String\n  storeId     String\n  orderValue  Float\n  commission  Float\n  status      String   @default(\"PENDING\")  // PENDING | APPROVED | PAID | REJECTED\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@index([orderId])\n  @@map(\"referral_conversions\")\n}\n\nmodel AffiliatePayout {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  amount      Float\n  method      String\n  status      String   @default(\"PENDING\")  // PENDING | SENT | FAILED\n  reference   String?\n  note        String?\n  createdAt   DateTime @default(now())\n\n  affiliate Affiliate @relation(fields: [affiliateId], references: [id], onDelete: Cascade)\n\n  @@index([affiliateId])\n  @@map(\"affiliate_payouts\")\n}\n\n// Affiliate click tracking\nmodel ReferralClick {\n  id          String   @id @default(uuid())\n  affiliateId String\n  storeId     String\n  ip          String?\n  userAgent   String?\n  page        String?\n  converted   Boolean  @default(false)\n  createdAt   DateTime @default(now())\n\n  @@index([affiliateId])\n  @@map(\"referral_clicks\")\n}\n\nenum AffiliateStatus {\n  PENDING\n  ACTIVE\n  PAUSED\n  SUSPENDED\n}\n\n// ─── Web Push Subscriptions ──────────────────────────────────────────────────\n\nmodel PushSubscription {\n  id       String   @id @default(uuid())\n  userId   String\n  endpoint String   @unique\n  p256dh   String   // public key\n  auth     String   // auth secret\n  deviceName String?  // e.g. \"Chrome on iPhone\"\n  isActive Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n\n// ─── Refund & Dispute ────────────────────────────────────────────────────────\n\nenum RefundStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  PROCESSED\n}\n\nenum RefundReason {\n  DAMAGED\n  NOT_RECEIVED\n  WRONG_ITEM\n  NOT_AS_DESCRIBED\n  CHANGED_MIND\n  OTHER\n}\n\nmodel Refund {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  amount      Float\n  reason      RefundReason\n  description String?\n  status      RefundStatus @default(PENDING)\n  gatewayRef  String?      // gateway refund ID\n  processedAt DateTime?\n  adminNote   String?\n  photos      String[]     @default([])\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"refunds\")\n}\n\n// ─── Customer Accounts ───────────────────────────────────────────────────────\n\nmodel CustomerAccount {\n  id            String    @id @default(uuid())\n  storeId       String\n  email         String\n  name          String\n  phone         String?\n  passwordHash  String\n  emailVerified Boolean   @default(false)\n  verifyToken   String?\n  resetToken    String?\n  resetExpiry   DateTime?\n  refreshToken  String?\n  defaultAddress Json?\n  savedAddresses Json[]   @default([])\n  wishlist       String[] @default([]) // productIds\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n\n  @@unique([storeId, email])\n  @@index([storeId])\n  @@map(\"customer_accounts\")\n}\n\n// ─── Wishlist ────────────────────────────────────────────────────────────────\n\nmodel Wishlist {\n  id         String   @id @default(uuid())\n  storeId    String\n  email      String\n  productId  String\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, email, productId])\n  @@index([storeId, email])\n  @@map(\"wishlists\")\n}\n\n// ─── Gift Card ───────────────────────────────────────────────────────────────\n\nmodel GiftCard {\n  id          String    @id @default(uuid())\n  storeId     String\n  code        String    @unique\n  balance     Float\n  initialAmount Float\n  currency    String    @default(\"USD\")\n  isActive    Boolean   @default(true)\n  purchasedBy String?   // email\n  assignedTo  String?   // email\n  expiresAt   DateTime?\n  note        String?\n  redeemedAmount Float  @default(0)\n  usages      GiftCardUsage[]\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([code])\n  @@map(\"gift_cards\")\n}\n\nmodel GiftCardUsage {\n  id         String   @id @default(uuid())\n  giftCardId String\n  orderId    String\n  amount     Float\n  createdAt  DateTime @default(now())\n\n  giftCard   GiftCard @relation(fields: [giftCardId], references: [id], onDelete: Cascade)\n\n  @@index([giftCardId])\n  @@map(\"gift_card_usages\")\n}\n\n// ─── Funnel Analytics ────────────────────────────────────────────────────────\n\nmodel FunnelEvent {\n  id        String   @id @default(uuid())\n  storeId   String\n  sessionId String\n  event     String   // \"view\" | \"add_to_cart\" | \"checkout_start\" | \"purchase\"\n  productId String?\n  orderId   String?\n  value     Float?\n  meta      Json?\n  ip        String?\n  userAgent String?\n  createdAt DateTime @default(now())\n\n  @@index([storeId])\n  @@index([sessionId])\n  @@index([event])\n  @@index([createdAt])\n  @@map(\"funnel_events\")\n}\n\n// ─── UTM / Traffic Source ────────────────────────────────────────────────────\n\nmodel UtmSession {\n  id         String   @id @default(uuid())\n  storeId    String\n  sessionId  String\n  source     String?\n  medium     String?\n  campaign   String?\n  term       String?\n  content    String?\n  landingPage String?\n  referrer   String?\n  converted  Boolean  @default(false)\n  orderId    String?\n  orderValue Float?\n  createdAt  DateTime @default(now())\n\n  @@unique([storeId, sessionId])\n  @@index([storeId])\n  @@index([source])\n  @@map(\"utm_sessions\")\n}\n\n// ─── API Keys (store owner) ─────────────────────────────────────────────────\n\nmodel ApiKey {\n  id          String    @id @default(uuid())\n  storeId     String\n  name        String\n  keyHash     String    @unique  // SHA-256 of actual key\n  keyPrefix   String             // first 8 chars for display\n  permissions String[]  @default([]) // [\"orders:read\",\"products:write\",...]\n  isActive    Boolean   @default(true)\n  lastUsedAt  DateTime?\n  expiresAt   DateTime?\n  createdAt   DateTime  @default(now())\n\n  store       Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@index([keyHash])\n  @@map(\"api_keys\")\n}\n\n// ─── Store Backup ────────────────────────────────────────────────────────────\n\nmodel StoreBackup {\n  id        String   @id @default(uuid())\n  storeId   String\n  fileName  String\n  fileUrl   String\n  fileSize  Int?     // bytes\n  status    String   @default(\"PENDING\") // PENDING | READY | FAILED\n  createdAt DateTime @default(now())\n\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"store_backups\")\n}\n\n// ─── Outgoing Webhooks (store owner) ────────────────────────────────────────\n\nmodel StoreWebhook {\n  id        String   @id @default(uuid())\n  storeId   String\n  url       String\n  events    String[] // [\"order.created\",\"order.paid\",\"product.updated\",...]\n  secret    String\n  isActive  Boolean  @default(true)\n  lastFiredAt DateTime?\n  failCount  Int     @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store      Store            @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  deliveries WebhookDelivery[]\n\n  @@index([storeId])\n  @@map(\"store_webhooks\")\n}\n\nmodel WebhookDelivery {\n  id         String   @id @default(uuid())\n  webhookId  String\n  event      String\n  payload    Json\n  statusCode Int?\n  response   String?\n  success    Boolean  @default(false)\n  createdAt  DateTime @default(now())\n\n  webhook StoreWebhook @relation(fields: [webhookId], references: [id], onDelete: Cascade)\n\n  @@index([webhookId])\n  @@map(\"webhook_deliveries\")\n}\n\n// ─── Flash Sale ──────────────────────────────────────────────────────────────\n\nmodel FlashSale {\n  id          String   @id @default(uuid())\n  storeId     String\n  name        String\n  discountPct Float\n  productIds  String[]\n  startsAt    DateTime\n  endsAt      DateTime\n  isActive    Boolean  @default(true)\n  bannerText  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  store       Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([storeId])\n  @@map(\"flash_sales\")\n}\n\n// ─── Return / RMA ────────────────────────────────────────────────────────────\n\nenum ReturnStatus {\n  REQUESTED\n  APPROVED\n  REJECTED\n  RECEIVED\n  REFUNDED\n}\n\nmodel ReturnRequest {\n  id          String       @id @default(uuid())\n  orderId     String\n  storeId     String\n  customerEmail String\n  reason      String\n  description String?\n  photos      String[]     @default([])\n  status      ReturnStatus @default(REQUESTED)\n  trackingNumber String?\n  adminNote   String?\n  resolvedAt  DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  order       Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  store       Store        @relation(fields: [storeId], references: [id], onDelete: Cascade)\n\n  @@index([orderId])\n  @@index([storeId])\n  @@map(\"return_requests\")\n}\n\n// ─── Subscription Products ───────────────────────────────────────────────────\n\nmodel ProductSubscription {\n  id            String   @id @default(uuid())\n  storeId       String\n  productId     String\n  customerEmail String\n  interval      String   // \"weekly\" | \"monthly\" | \"quarterly\"\n  intervalCount Int      @default(1)\n  price         Float\n  currency      String   @default(\"USD\")\n  discount      Float    @default(0) // % off for subscribing\n  status        String   @default(\"ACTIVE\") // ACTIVE | PAUSED | CANCELLED\n  nextBillingAt DateTime\n  stripeSubId   String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@index([storeId])\n  @@index([customerEmail])\n  @@map(\"product_subscriptions\")\n}\n\n// ─── Cohort Analytics ────────────────────────────────────────────────────────\n\nmodel CohortData {\n  id        String   @id @default(uuid())\n  storeId   String\n  cohortMonth String  // \"2025-01\"\n  totalCustomers Int @default(0)\n  day30Return    Int @default(0)\n  day60Return    Int @default(0)\n  day90Return    Int @default(0)\n  calculatedAt   DateTime @default(now())\n\n  @@unique([storeId, cohortMonth])\n  @@index([storeId])\n  @@map(\"cohort_data\")\n}\n\n// ─── KAI Chat History ─────────────────────────────────────────────────────────\n\nmodel KaiConversation {\n  id        String       @id @default(uuid())\n  userId    String\n  title     String       @default(\"New Chat\")\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n  messages  KaiMessage[]\n\n  user      User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"kai_conversations\")\n}\n\nmodel KaiMessage {\n  id             String          @id @default(uuid())\n  conversationId String\n  role           String          // \"user\" | \"assistant\"\n  content        String          @db.Text\n  action         String?\n  createdAt      DateTime        @default(now())\n\n  conversation   KaiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId])\n  @@map(\"kai_messages\")\n}\n\n\nmodel StoreIntegration {\n  id           String    @id @default(cuid())\n  storeId      String\n  store        Store     @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  provider     String\n  email        String?\n  password     String?\n  accessToken  String?   @db.Text\n  refreshToken String?\n  expiresAt    DateTime?\n  isActive     Boolean   @default(true)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@unique([storeId, provider], name: \"storeId_provider\")\n  @@index([storeId])\n}\n\nmodel WaitlistEntry {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  whatsapp     String?\n  spotNumber   Int      @unique\n  referralCode String   @unique\n  referredBy   String?\n  source       String?\n  ipHash       String?\n  confirmed    Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@index([email])\n  @@index([referralCode])\n  @@index([spotNumber])\n}\n\nmodel Bundle {\n  id              String   @id @default(uuid())\n  storeId         String\n  store           Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  name            String\n  productIds      String[]\n  discountPercent Float    @default(10)\n  bundlePrice     Float?\n  originalPrice   Float?\n  active          Boolean  @default(true)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\nmodel GroupBuy {\n  id              String        @id @default(uuid())\n  storeId         String\n  store           Store         @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  productId       String\n  product         Product       @relation(fields: [productId], references: [id])\n  title           String\n  description     String?\n  groupPrice      Float\n  originalPrice   Float\n  minMembers      Int\n  endsAt          DateTime\n  active          Boolean       @default(true)\n  members         GroupBuyMember[]\n  createdAt       DateTime      @default(now())\n}\n\nmodel GroupBuyMember {\n  id          String   @id @default(uuid())\n  groupBuyId  String\n  groupBuy    GroupBuy @relation(fields: [groupBuyId], references: [id], onDelete: Cascade)\n  name        String\n  email       String\n  paid        Boolean  @default(false)\n  createdAt   DateTime @default(now())\n}\n\nmodel Milestone {\n  id        String   @id @default(uuid())\n  storeId   String\n  store     Store    @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  type      String\n  title     String\n  message   String\n  cta       Json?\n  seen      Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel ContactMessage {\n  id        String   @id @default(uuid())\n  name      String\n  email     String\n  subject   String   @default(\"general\")\n  message   String\n  status    String   @default(\"new\")\n  createdAt DateTime @default(now())\n}\n\nmodel Referral {\n  id          String   @id @default(uuid())\n  userId      String   @unique\n  user        User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  code        String   @unique\n  clicks      Int      @default(0)\n  signups     Int      @default(0)\n  conversions Int      @default(0)\n  earned      Float    @default(0)\n  pending     Float    @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n","backend/src/app.ts":"import \"express-async-errors\";\n\nimport express, { Request, Response, NextFunction } from \"express\";\nimport cors from \"cors\";\nimport helmet from \"helmet\";\nimport compression from \"compression\";\nimport morgan from \"morgan\";\nimport cookieParser from \"cookie-parser\";\nimport path from \"path\";\n\n// Middleware\nimport { globalRateLimiter } from \"./middleware/rateLimiter\";\nimport { errorHandler } from \"./middleware/errorHandler\";\nimport { notFound } from \"./middleware/notFound\";\nimport { requestLogger } from \"./middleware/requestLogger\";\n\n// Core Routes\nimport authRoutes        from \"./routes/auth.routes\";\nimport storeRoutes       from \"./routes/store.routes\";\nimport productRoutes     from \"./routes/product.routes\";\nimport orderRoutes       from \"./routes/order.routes\";\nimport paymentRoutes     from \"./routes/payment.routes\";\nimport customerRoutes    from \"./routes/customer.routes\";\nimport adminRoutes       from \"./routes/admin.routes\";\nimport analyticsRoutes   from \"./routes/analytics.routes\";\nimport uploadRoutes      from \"./routes/upload.routes\";\nimport supportRoutes     from \"./routes/support.routes\";\nimport notificationRoutes from \"./routes/notification.routes\";\nimport couponRoutes      from \"./routes/coupon.routes\";\nimport discountRoutes    from \"./routes/discount.routes\";\nimport affiliateRoutes   from \"./routes/affiliate.routes\";\nimport aiRoutes          from \"./routes/ai.routes\";\nimport pushRoutes        from \"./routes/push.routes\";\nimport shippingRoutes    from \"./routes/shipping.routes\";\nimport reviewRoutes      from \"./routes/review.routes\";\nimport invoiceRoutes     from \"./routes/invoice.routes\";\nimport emailRoutes       from \"./routes/email.routes\";\nimport upsellRoutes      from \"./routes/upsell.routes\";\nimport abandonedCartRoutes from \"./routes/abandonedCart.routes\";\nimport notifSettingsRoutes from \"./routes/notificationSettings.routes\";\nimport currencyRoutes      from \"./routes/currency.routes\";\nimport supplierRoutes      from \"./routes/supplier.routes\";\nimport refundRoutes        from \"./routes/refund.routes\";\nimport giftCardRoutes      from \"./routes/giftCard.routes\";\nimport customerAccountRoutes from \"./routes/customerAccount.routes\";\nimport funnelRoutes        from \"./routes/funnel.routes\";\nimport apiKeyRoutes        from \"./routes/apiKey.routes\";\nimport webhookRoutes       from \"./routes/webhook.routes\";\nimport returnsRoutes       from \"./routes/returns.routes\";\nimport twoFARoutes         from \"./routes/twoFA.routes\";\nimport productSubscriptionRoutes from \"./routes/productSubscription.routes\";\nimport onboardingRoutes  from \"./routes/onboarding.routes\";\nimport milestoneRoutes   from \"./routes/milestone.routes\";\nimport contactRoutes     from \"./routes/contact.routes\";\nimport bundleRoutes      from \"./routes/bundle.routes\";\nimport groupBuyRoutes    from \"./routes/groupbuy.routes\";\nimport referralRoutes    from \"./routes/referral.routes\";\nimport navLevelRoutes    from \"./routes/navlevel.routes\";\nimport reportsRoutes     from \"./routes/reports.routes\";\nimport waitlistRoutes      from \"./routes/waitlist.routes\";\n\n// KAI CORE\nimport kaiRoutes from \"./routes/kai.routes\";\n\n// KAI EXPANSIONS\nimport kaiPowerRoutes from \"./routes/kai.power.routes\";\nimport featuresRoutes from \"./routes/features.routes\";\nimport loyaltyRoutes from \"./routes/loyalty.routes\";\nimport superchargeRoutes from \"./routes/supercharge.routes\";\nimport kaiAgentRoutes from \"./routes/kai.agent.routes\";\nimport themeRoutes from \"./routes/theme.routes\";\n\n// Controllers (Advanced AI + Automation)\nimport productIntelRoutes from \"./controllers/product.intel.controller\";\nimport intelRoutes from \"./controllers/kai.intelligence.controller\";\nimport fulfillmentRoutes from \"./controllers/fulfillment.controller\";\n\nconst app = express();\n\n// TRUST PROXY\nif (process.env.NODE_ENV === \"production\") {\n  app.set(\"trust proxy\", 1);\n}\n\n// SECURITY\napp.use(helmet({\n  crossOriginResourcePolicy: { policy: \"cross-origin\" },\n  contentSecurityPolicy: {\n    directives: {\n      defaultSrc: [\"'self'\"],\n      scriptSrc: [\"'self'\", \"https://js.stripe.com\"],\n      frameSrc: [\"'self'\", \"https://js.stripe.com\"],\n      connectSrc: [\"'self'\", \"https://api.stripe.com\"],\n      imgSrc: [\"'self'\", \"data:\", \"https:\"],\n      styleSrc: [\"'self'\", \"'unsafe-inline'\"],\n    },\n  },\n}));\n\n// CORS\nconst allowedOrigins = [\n  process.env.FRONTEND_URL || \"http://localhost:3000\",\n  \"http://localhost:3000\",\n  \"https://dropos-frontend1.vercel.app\",\n  \"https://droposhq.com\",\n  \"https://www.droposhq.com\",\n].filter(Boolean);\n\napp.use(cors({\n  origin: (origin, callback) => {\n    if (!origin || allowedOrigins.includes(origin) || origin.endsWith(\".vercel.app\")) {\n      callback(null, true);\n    } else {\n      callback(null, true);\n    }\n  },\n  credentials: true,\n}));\n\n// WEBHOOK RAW BODY\napp.use(\"/api/payments/webhook/stripe\", express.raw({ type: \"application/json\" }));\napp.use(\"/api/payments/webhook/paystack\", express.raw({ type: \"application/json\" }));\napp.use(\"/api/payments/webhook/flutterwave\", express.raw({ type: \"application/json\" }));\n\n// BODY PARSER\napp.use(express.json({ limit: \"2mb\" }));\napp.use(express.urlencoded({ extended: true, limit: \"2mb\" }));\napp.use(cookieParser());\napp.use(compression());\n\n// QUERY SANITIZATION\napp.use((req, _res, next) => {\n  for (const key in req.query) {\n    if (Array.isArray(req.query[key])) {\n      req.query[key] = (req.query[key] as string[]).at(-1) as any;\n    }\n  }\n  next();\n});\n\n// STATIC\napp.use(\"/uploads\", express.static(path.join(process.cwd(), \"uploads\")));\n\n// LOGGING\nif (process.env.NODE_ENV !== \"test\") {\n  app.use(morgan(\"combined\"));\n  app.use(requestLogger);\n}\n\n// RATE LIMIT\napp.use(\"/api\", globalRateLimiter);\n\n// HEALTH\napp.get(\"/api/health\", (_req: Request, res: Response) => {\n  res.json({ status: \"ok\", service: \"DropOS API\" });\n});\n\n// CORE BUSINESS ROUTES\napp.use(\"/api/auth\",                 authRoutes);\napp.use(\"/api/stores\",               storeRoutes);\napp.use(\"/api/products\",             productRoutes);\napp.use(\"/api/orders\",               orderRoutes);\napp.use(\"/api/payments\",             paymentRoutes);\napp.use(\"/api/customers\",            customerRoutes);\napp.use(\"/api/admin\",                adminRoutes);\napp.use(\"/api/analytics\",            analyticsRoutes);\napp.use(\"/api/upload\",               uploadRoutes);\napp.use(\"/api/support\",              supportRoutes);\napp.use(\"/api/notifications\",        notificationRoutes);\napp.use(\"/api/coupons\",              couponRoutes);\napp.use(\"/api/discounts\",            discountRoutes);\napp.use(\"/api/affiliates\",           affiliateRoutes);\napp.use(\"/api/ai\",                   aiRoutes);\napp.use(\"/api/push\",                 pushRoutes);\napp.use(\"/api/shipping\",             shippingRoutes);\napp.use(\"/api/reviews\",              reviewRoutes);\napp.use(\"/api/invoices\",             invoiceRoutes);\napp.use(\"/api/email\",                emailRoutes);\napp.use(\"/api/abandoned-carts\",      abandonedCartRoutes);\napp.use(\"/api/notification-settings\",notifSettingsRoutes);\napp.use(\"/api/currency\",             currencyRoutes);\napp.use(\"/api/suppliers\",            supplierRoutes);\napp.use(\"/api/refunds\",              refundRoutes);\napp.use(\"/api/gift-cards\",           giftCardRoutes);\napp.use(\"/api/customer-auth\",        customerAccountRoutes);\napp.use(\"/api/funnel\",               funnelRoutes);\napp.use(\"/api/api-keys\",             apiKeyRoutes);\napp.use(\"/api/webhooks\",             webhookRoutes);\napp.use(\"/api/ops\",                  returnsRoutes);\napp.use(\"/api/2fa\",                  twoFARoutes);\napp.use(\"/api/product-subscriptions\",productSubscriptionRoutes);\napp.use(\"/api/upsell\",               upsellRoutes);\napp.use(\"/api/waitlist\",             waitlistRoutes);\n\n// KAI SYSTEM\napp.use(\"/api/kai\",              kaiRoutes);\napp.use(\"/api/kai/power\",        kaiPowerRoutes);\napp.use(\"/api/kai/agent\",        kaiAgentRoutes);\napp.use(\"/api/features\",         featuresRoutes);\napp.use(\"/api/loyalty\",          loyaltyRoutes);\napp.use(\"/api/super\",            superchargeRoutes);\napp.use(\"/api/theme\",            themeRoutes);\napp.use(\"/api/products/intel\",   productIntelRoutes);\napp.use(\"/api/intel\",            intelRoutes);\napp.use(\"/api/fulfillment\",      fulfillmentRoutes);\n\n// ERRORS\napp.use(\"/api/onboarding\",    onboardingRoutes);\napp.use(\"/api/milestones\",     milestoneRoutes);\napp.use(\"/api/contact\",        contactRoutes);\napp.use(\"/api/bundles\",        bundleRoutes);\napp.use(\"/api/group-buy\",      groupBuyRoutes);\napp.use(\"/api/referral\",       referralRoutes);\napp.use(\"/api/nav-level\",      navLevelRoutes);\napp.use(\"/api/reports\",        reportsRoutes);\napp.use(notFound);\napp.use(errorHandler);\n\nexport default app;","backend/src/routes/onboarding.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// POST /api/onboarding/complete\nrouter.post(\"/complete\", async (req: any, res: Response) => {\n  try {\n    const { niche, stage, goal, template } = req.body;\n    const userId  = req.user.id;\n    const storeId = req.user.stores?.[0]?.id;\n\n    // Update user as onboarded\n    const user = await prisma.user.update({\n      where: { id: userId },\n      data: { onboarded: true, onboardNiche: niche, onboardStage: stage, onboardGoal: goal, onboardTemplate: template },\n    });\n\n    // Apply template to store if exists\n    if (storeId && template) {\n      await prisma.store.update({\n        where: { id: storeId },\n        data: { templateId: template, primaryColor: getColorForNiche(niche) },\n      }).catch(() => {}); // Non-critical\n    }\n\n    // Generate KIRO welcome message based on answers\n    const nicheLabels: Record<string,string> = {\n      hair:\"Hair and Beauty\", fashion:\"Fashion and Clothing\", electronics:\"Electronics\",\n      food:\"Food and Drinks\", skincare:\"Skincare and Wellness\", home:\"Home and Living\",\n      kids:\"Kids and Baby\", other:\"your niche\",\n    };\n    const nicheLabel = nicheLabels[niche] || \"your niche\";\n\n    const kiroMessage = `Perfect. I am setting up your ${nicheLabel} store right now. I am picking the best template, importing trending products in your category, and configuring Paystack for Nigerian buyers. This takes about 10 seconds.`;\n\n    // Create first milestone: store setup\n    if (storeId) {\n      await prisma.milestone.create({\n        data: {\n          storeId, type: \"store_complete\",\n          title: \"Your store is live\",\n          message: `KIRO has set up your ${nicheLabel} store. Share your link and get your first sale today.`,\n          cta: { label: \"View your store\", href: \"/dashboard/stores\" },\n        },\n      }).catch(() => {});\n    }\n\n    res.json({ success: true, data: { kiroMessage, user: { ...user, password: undefined } } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nfunction getColorForNiche(niche: string): string {\n  const colors: Record<string,string> = {\n    hair:\"#E91E8C\", fashion:\"#8B5CF6\", electronics:\"#06B6D4\",\n    food:\"#F59E0B\", skincare:\"#10B981\", home:\"#F97316\", kids:\"#EC4899\",\n  };\n  return colors[niche] || \"#6B35E8\";\n}\n\nexport default router;\n","backend/src/routes/milestone.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/milestones/:storeId\nrouter.get(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const milestones = await prisma.milestone.findMany({\n      where: { storeId: req.params.storeId },\n      orderBy: { createdAt: \"desc\" },\n      take: 20,\n    });\n    res.json({ success: true, data: milestones });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// PATCH /api/milestones/:id/seen\nrouter.patch(\"/:id/seen\", async (req: any, res: Response) => {\n  try {\n    await prisma.milestone.update({ where: { id: req.params.id }, data: { seen: true } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// Internal: create milestone (called from other services)\nexport async function createMilestone(storeId: string, type: string, title: string, message: string, cta?: any) {\n  return prisma.milestone.create({ data: { storeId, type, title, message, cta } });\n}\n\nexport default router;\n","backend/src/routes/contact.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\n\n// POST /api/contact\nrouter.post(\"/\", async (req: Request, res: Response) => {\n  try {\n    const { name, email, subject, message } = req.body;\n    if (!name || !email || !message) {\n      return res.status(400).json({ success: false, message: \"Name, email and message are required\" });\n    }\n    await prisma.contactMessage.create({ data: { name, email, subject: subject || \"general\", message } });\n    // TODO: send email notification to hello@droposhq.com via Resend\n    res.json({ success: true, message: \"Message received. We will reply within 24 hours.\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/bundle.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/bundles/:storeId\nrouter.get(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const bundles = await prisma.bundle.findMany({\n      where: { storeId: req.params.storeId },\n      orderBy: { createdAt: \"desc\" },\n    });\n    res.json({ success: true, data: bundles });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// POST /api/bundles/:storeId\nrouter.post(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const { name, productIds, discountPercent } = req.body;\n    if (!name || !productIds?.length) return res.status(400).json({ success: false, message: \"Name and products required\" });\n\n    // Get products to calculate price\n    const products = await prisma.product.findMany({ where: { id: { in: productIds } } });\n    const originalPrice = products.reduce((a: number, p: any) => a + (p.price || 0), 0);\n    const bundlePrice   = originalPrice * (1 - (discountPercent || 10) / 100);\n\n    const bundle = await prisma.bundle.create({\n      data: { storeId: req.params.storeId, name, productIds, discountPercent: discountPercent || 10, originalPrice, bundlePrice },\n    });\n    res.status(201).json({ success: true, data: bundle });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// DELETE /api/bundles/:storeId/:bundleId\nrouter.delete(\"/:storeId/:bundleId\", async (req: any, res: Response) => {\n  try {\n    await prisma.bundle.delete({ where: { id: req.params.bundleId } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/groupbuy.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\n\n// Public: GET /api/group-buy/public/:id\nrouter.get(\"/public/:id\", async (req: Request, res: Response) => {\n  try {\n    const gb = await prisma.groupBuy.findUnique({\n      where: { id: req.params.id },\n      include: {\n        store:   { select: { name: true, slug: true, logo: true, primaryColor: true, currency: true } },\n        product: { select: { name: true, images: true, price: true } },\n        members: { select: { name: true, createdAt: true }, orderBy: { createdAt: \"asc\" } },\n      },\n    });\n    if (!gb) return res.status(404).json({ success: false, message: \"Group buy not found\" });\n    res.json({ success: true, data: { ...gb, memberCount: gb.members.length } });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// Public: POST /api/group-buy/:id/join\nrouter.post(\"/:id/join\", async (req: Request, res: Response) => {\n  try {\n    const { name, email } = req.body;\n    if (!name || !email) return res.status(400).json({ success: false, message: \"Name and email required\" });\n\n    const gb = await prisma.groupBuy.findUnique({ where: { id: req.params.id } });\n    if (!gb || !gb.active) return res.status(404).json({ success: false, message: \"Group buy not found or ended\" });\n    if (new Date(gb.endsAt) < new Date()) return res.status(400).json({ success: false, message: \"Group buy has ended\" });\n\n    // Check if already joined\n    const existing = await prisma.groupBuyMember.findFirst({ where: { groupBuyId: req.params.id, email } });\n    if (existing) return res.status(400).json({ success: false, message: \"You have already joined this group buy\" });\n\n    await prisma.groupBuyMember.create({ data: { groupBuyId: req.params.id, name, email } });\n    res.json({ success: true, message: \"Joined! We will email you when the group fills up.\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// Authenticated: POST /api/group-buy (create)\nrouter.post(\"/\", authenticate as any, async (req: any, res: Response) => {\n  try {\n    const { storeId, productId, title, description, groupPrice, originalPrice, minMembers, endsAt } = req.body;\n    const gb = await prisma.groupBuy.create({\n      data: { storeId, productId, title, description, groupPrice, originalPrice, minMembers: minMembers || 10, endsAt: new Date(endsAt) },\n    });\n    res.status(201).json({ success: true, data: gb });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// GET /api/group-buy/store/:storeId (list)\nrouter.get(\"/store/:storeId\", authenticate as any, async (req: any, res: Response) => {\n  try {\n    const gbs = await prisma.groupBuy.findMany({\n      where: { storeId: req.params.storeId },\n      include: { _count: { select: { members: true } } },\n      orderBy: { createdAt: \"desc\" },\n    });\n    res.json({ success: true, data: gbs });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/referral.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\nimport crypto from \"crypto\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/referral/stats\nrouter.get(\"/stats\", async (req: any, res: Response) => {\n  try {\n    let referral = await prisma.referral.findUnique({ where: { userId: req.user.id } });\n    if (!referral) {\n      const code = crypto.randomBytes(4).toString(\"hex\").toUpperCase();\n      referral = await prisma.referral.create({ data: { userId: req.user.id, code } });\n    }\n    res.json({ success: true, data: referral });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\n// POST /api/referral/click (track referral click)\nrouter.post(\"/click\", async (req: Request, res: Response) => {\n  try {\n    const { code } = req.body;\n    if (!code) return res.status(400).json({ success: false });\n    await prisma.referral.update({ where: { code }, data: { clicks: { increment: 1 } } }).catch(() => {});\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/navlevel.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// GET /api/nav-level/:storeId\nrouter.get(\"/:storeId\", async (req: any, res: Response) => {\n  try {\n    const storeId = req.params.storeId;\n    const [productCount, orderCount, store] = await Promise.all([\n      prisma.product.count({ where: { storeId } }),\n      prisma.order.count({ where: { storeId } }),\n      prisma.store.findUnique({ where: { id: storeId }, select: { paystackConnected: true } }),\n    ]);\n    res.json({\n      success: true,\n      data: { productCount, orderCount, hasPaystack: store?.paystackConnected ?? false },\n    });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","backend/src/routes/reports.routes.ts":"import { Router, Request, Response } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport { prisma } from \"../lib/prisma\";\n\nconst router = Router();\nrouter.use(authenticate);\n\nfunction toCSV(headers: string[], rows: any[][]): string {\n  const escape = (v: any) => `\"${String(v ?? \"\").replace(/\"/g, '\"\"')}\"`;\n  return [headers.map(escape).join(\",\"), ...rows.map(r => r.map(escape).join(\",\"))].join(\"\\n\");\n}\n\n// GET /api/reports/:storeId/:reportId\nrouter.get(\"/:storeId/:reportId\", async (req: any, res: Response) => {\n  try {\n    const { storeId, reportId } = req.params;\n    const period = parseInt(req.query.period as string) || 30;\n    const format = req.query.format as string || \"csv\";\n    const since  = new Date(Date.now() - period * 86400000);\n\n    let csv = \"\";\n    let filename = `dropos-${reportId}`;\n\n    switch (reportId) {\n      case \"revenue\": {\n        const orders = await prisma.order.findMany({\n          where: { storeId, createdAt: { gte: since } },\n          select: { id: true, orderNumber: true, total: true, status: true, createdAt: true },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Order ID\", \"Order Number\", \"Total (NGN)\", \"Status\", \"Date\"],\n          orders.map(o => [o.id, o.orderNumber, o.total, o.status, o.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-revenue-${period}days`;\n        break;\n      }\n      case \"orders\": {\n        const orders = await prisma.order.findMany({\n          where: { storeId, createdAt: { gte: since } },\n          include: { customer: { select: { name: true, email: true } }, items: { include: { product: { select: { name: true } } } } },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Order ID\", \"Customer Name\", \"Customer Email\", \"Items\", \"Total\", \"Status\", \"Date\"],\n          orders.map(o => [\n            o.id, o.customer?.name ?? \"Guest\", o.customer?.email ?? \"\",\n            o.items.map((i: any) => i.product?.name ?? \"\").join(\"; \"),\n            o.total, o.status, o.createdAt.toISOString().split(\"T\")[0],\n          ])\n        );\n        filename = `dropos-orders-${period}days`;\n        break;\n      }\n      case \"customers\": {\n        const customers = await prisma.storeCustomer.findMany({\n          where: { storeId },\n          include: { _count: { select: { orders: true } } },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Customer ID\", \"Name\", \"Email\", \"Phone\", \"Total Orders\", \"Joined\"],\n          customers.map(c => [c.id, c.name, c.email, c.phone ?? \"\", c._count.orders, c.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-customers`;\n        break;\n      }\n      case \"products\": {\n        const products = await prisma.product.findMany({\n          where: { storeId },\n          select: { id: true, name: true, price: true, inventory: true, status: true, createdAt: true },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Product ID\", \"Name\", \"Price (NGN)\", \"Stock\", \"Status\", \"Created\"],\n          products.map(p => [p.id, p.name, p.price, p.inventory, p.status, p.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-products`;\n        break;\n      }\n      case \"inventory\": {\n        const products = await prisma.product.findMany({\n          where: { storeId },\n          select: { id: true, name: true, sku: true, inventory: true, price: true },\n        });\n        csv = toCSV(\n          [\"Product ID\", \"Name\", \"SKU\", \"Stock\", \"Price (NGN)\"],\n          products.map(p => [p.id, p.name, p.sku ?? \"\", p.inventory, p.price])\n        );\n        filename = `dropos-inventory`;\n        break;\n      }\n      case \"tax\": {\n        const orders = await prisma.order.findMany({\n          where: { storeId, createdAt: { gte: since } },\n          select: { id: true, orderNumber: true, total: true, tax: true, createdAt: true },\n          orderBy: { createdAt: \"desc\" },\n        });\n        csv = toCSV(\n          [\"Order ID\", \"Order Number\", \"Subtotal\", \"Tax\", \"Date\"],\n          orders.map(o => [o.id, o.orderNumber, (o.total - (o.tax || 0)).toFixed(2), (o.tax || 0).toFixed(2), o.createdAt.toISOString().split(\"T\")[0]])\n        );\n        filename = `dropos-tax-${period}days`;\n        break;\n      }\n      default:\n        return res.status(400).json({ success: false, message: \"Unknown report type\" });\n    }\n\n    res.setHeader(\"Content-Type\", \"text/csv\");\n    res.setHeader(\"Content-Disposition\", `attachment; filename=\"${filename}.csv\"`);\n    res.send(csv);\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n});\n\nexport default router;\n","frontend/src/app/dashboard/page.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { motion } from \"framer-motion\";\nimport Link from \"next/link\";\nimport { TrendingUp, ShoppingCart, Users, Package, Zap, Sparkles, ChevronRight, AlertCircle, Store, Flame, Activity } from \"lucide-react\";\nimport { useTheme } from \"../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../store/auth.store\";\n\nexport default function DashboardPage() {\n  const { theme } = useTheme();\n  const { user } = useAuthStore();\n  const isDark = theme === \"dark\";\n  const firstName = user?.name?.split(\" \")[0] || user?.email?.split(\"@\")[0] || \"there\";\n  const [greeting, setGreeting] = useState(\"morning\");\n\n  useEffect(() => {\n    const h = new Date().getHours();\n    setGreeting(h < 12 ? \"morning\" : h < 17 ? \"afternoon\" : \"evening\");\n  }, []);\n\n  const t = {\n    card: isDark ? \"#181230\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(15,5,32,0.07)\",\n    text: isDark ? \"#fff\" : \"#0D0918\",\n    muted: isDark ? \"rgba(255,255,255,0.38)\" : \"rgba(13,9,24,0.45)\",\n    shadow: isDark ? \"none\" : \"0 1px 3px rgba(15,5,32,0.04), 0 4px 20px rgba(15,5,32,0.03)\",\n  };\n\n  const stats = [\n    { label: \"Total Revenue\", value: \"N0\",   color: \"#8B5CF6\", icon: TrendingUp },\n    { label: \"Total Orders\",  value: \"0\",    color: \"#06B6D4\", icon: ShoppingCart },\n    { label: \"Customers\",     value: \"0\",    color: \"#10B981\", icon: Users },\n    { label: \"Products\",      value: \"0\",    color: \"#C026D3\", icon: Package },\n  ];\n\n  return (\n    <div style={{ maxWidth: 1400, margin: \"0 auto\" }}>\n      <motion.div initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }}\n        style={{ display: \"flex\", alignItems: \"flex-start\", justifyContent: \"space-between\", gap: 16, marginBottom: 28 }}>\n        <div>\n          <h1 style={{ fontSize: 22, fontWeight: 800, letterSpacing: \"-0.03em\", color: t.text }}>\n            Good {greeting}, {firstName}\n          </h1>\n          <p style={{ fontSize: 13, marginTop: 4, color: t.muted }}>Here's what's happening with your store today.</p>\n        </div>\n        <Link href=\"/dashboard/kai\">\n          <motion.button whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.97 }}\n            style={{ display: \"flex\", alignItems: \"center\", gap: 8, padding: \"10px 20px\", borderRadius: 14, border: \"none\", cursor: \"pointer\", background: \"linear-gradient(135deg, #6B35E8, #3D1C8A)\", color: \"#fff\", fontSize: 13, fontWeight: 700, whiteSpace: \"nowrap\", boxShadow: \"0 6px 24px rgba(107,53,232,0.35)\" }}>\n            <Zap size={14} color=\"white\" /> Ask KIRO <ChevronRight size={13} color=\"rgba(255,255,255,0.6)\" />\n          </motion.button>\n        </Link>\n      </motion.div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(4, 1fr)\", gap: 14, marginBottom: 20 }}>\n        {stats.map((s, i) => {\n          const Icon = s.icon;\n          return (\n            <motion.div key={s.label} initial={{ opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08 }}\n              style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}`, boxShadow: t.shadow }}>\n              <div style={{ width: 38, height: 38, borderRadius: 11, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${s.color}15`, marginBottom: 14 }}>\n                <Icon size={17} color={s.color} />\n              </div>\n              <div style={{ fontSize: 26, fontWeight: 800, letterSpacing: \"-0.04em\", color: t.text, marginBottom: 6 }}>{s.value}</div>\n              <span style={{ fontSize: 12, color: t.muted }}>{s.label}</span>\n            </motion.div>\n          );\n        })}\n      </div>\n\n      <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 308px\", gap: 16 }}>\n        <motion.div initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}\n          style={{ padding: 20, borderRadius: 16, background: t.card, border: `1px solid ${t.border}`, boxShadow: t.shadow }}>\n          <div style={{ display: \"flex\", alignItems: \"center\", justifyContent: \"space-between\", marginBottom: 16 }}>\n            <span style={{ fontSize: 14, fontWeight: 700, color: t.text }}>Recent Orders</span>\n          </div>\n          <div style={{ display: \"flex\", flexDirection: \"column\", alignItems: \"center\", justifyContent: \"center\", padding: \"48px 24px\", textAlign: \"center\" }}>\n            <div style={{ width: 52, height: 52, borderRadius: 16, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", marginBottom: 14, background: isDark ? \"rgba(255,255,255,0.04)\" : \"rgba(15,5,32,0.04)\" }}>\n              <ShoppingCart size={22} color={isDark ? \"rgba(255,255,255,0.2)\" : \"rgba(15,5,32,0.2)\"} />\n            </div>\n            <p style={{ fontSize: 13, fontWeight: 600, marginBottom: 4, color: t.muted }}>No orders yet</p>\n            <p style={{ fontSize: 12, marginBottom: 16, color: isDark ? \"rgba(255,255,255,0.22)\" : \"rgba(15,5,32,0.28)\" }}>Your first order will appear here</p>\n            <Link href=\"/dashboard/kai\">\n              <div style={{ display: \"flex\", alignItems: \"center\", gap: 6, padding: \"8px 16px\", borderRadius: 12, fontSize: 12, fontWeight: 600, cursor: \"pointer\", background: \"rgba(107,53,232,0.12)\", color: \"#A78BFA\" }}>\n                <Zap size={12} /> Ask KIRO to help get first sales\n              </div>\n            </Link>\n          </div>\n        </motion.div>\n\n        <div style={{ display: \"flex\", flexDirection: \"column\", gap: 14 }}>\n          <motion.div initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.35 }}\n            style={{ borderRadius: 16, padding: 18, background: isDark ? \"linear-gradient(135deg, rgba(107,53,232,0.1), rgba(91,33,182,0.05))\" : \"linear-gradient(135deg, rgba(107,53,232,0.06), rgba(91,33,182,0.02))\", border: \"1px solid rgba(107,53,232,0.22)\" }}>\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 8, marginBottom: 14 }}>\n              <div style={{ width: 28, height: 28, borderRadius: 8, background: \"linear-gradient(145deg, #6B35E8, #1A0D3D)\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}>\n                <Zap size={13} color=\"white\" />\n              </div>\n              <span style={{ fontSize: 13, fontWeight: 700, color: isDark ? \"#C4B5FD\" : \"#3D1C8A\" }}>KIRO Insights</span>\n            </div>\n            <div style={{ display: \"flex\", flexDirection: \"column\", gap: 8, marginBottom: 14 }}>\n              {[\n                { text: \"Your store is ready. Ask KIRO to set up your first product collection.\", color: \"#8B5CF6\", bg: \"rgba(107,53,232,0.08)\", border: \"rgba(107,53,232,0.18)\", icon: Sparkles },\n                { text: \"Enable abandoned cart recovery — KIRO recovers up to 15% of lost sales.\", color: \"#10B981\", bg: \"rgba(16,185,129,0.07)\", border: \"rgba(16,185,129,0.18)\", icon: TrendingUp },\n                { text: \"Add a custom domain to build trust with customers.\", color: \"#F59E0B\", bg: \"rgba(245,158,11,0.07)\", border: \"rgba(245,158,11,0.18)\", icon: AlertCircle },\n              ].map((ins, i) => {\n                const Icon = ins.icon;\n                return (\n                  <div key={i} style={{ display: \"flex\", alignItems: \"flex-start\", gap: 9, padding: 10, borderRadius: 11, background: ins.bg, border: `1px solid ${ins.border}` }}>\n                    <div style={{ width: 24, height: 24, borderRadius: 7, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0, background: `${ins.color}20` }}>\n                      <Icon size={11} color={ins.color} />\n                    </div>\n                    <p style={{ fontSize: 11.5, lineHeight: 1.55, color: t.muted }}>{ins.text}</p>\n                  </div>\n                );\n              })}\n            </div>\n            <Link href=\"/dashboard/kai\">\n              <button style={{ width: \"100%\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", gap: 7, padding: 10, borderRadius: 12, border: \"none\", cursor: \"pointer\", background: \"linear-gradient(135deg, #6B35E8, #3D1C8A)\", color: \"#fff\", fontSize: 12, fontWeight: 700 }}>\n                <Zap size={12} color=\"white\" /> Chat with KIRO\n              </button>\n            </Link>\n          </motion.div>\n\n          <motion.div initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}\n            style={{ padding: 18, borderRadius: 16, background: t.card, border: `1px solid ${t.border}`, boxShadow: t.shadow }}>\n            <span style={{ fontSize: 13, fontWeight: 700, color: t.text, display: \"block\", marginBottom: 14 }}>Quick Actions</span>\n            <div style={{ display: \"grid\", gridTemplateColumns: \"1fr 1fr\", gap: 8 }}>\n              {[\n                { label: \"Add Product\", href: \"/dashboard/products\", icon: Package, color: \"#8B5CF6\" },\n                { label: \"View Store\", href: \"#\", icon: Store, color: \"#06B6D4\" },\n                { label: \"Flash Sale\", href: \"/dashboard/flash-sales\", icon: Flame, color: \"#F59E0B\" },\n                { label: \"Analytics\", href: \"/dashboard/analytics\", icon: Activity, color: \"#10B981\" },\n              ].map(a => {\n                const Icon = a.icon;\n                return (\n                  <Link href={a.href} key={a.label}>\n                    <motion.div whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.97 }}\n                      style={{ display: \"flex\", flexDirection: \"column\", alignItems: \"center\", gap: 8, padding: 12, borderRadius: 12, cursor: \"pointer\", background: isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(15,5,32,0.03)\", border: `1px solid ${t.border}` }}>\n                      <div style={{ width: 32, height: 32, borderRadius: 10, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", background: `${a.color}15` }}>\n                        <Icon size={15} color={a.color} />\n                      </div>\n                      <span style={{ fontSize: 11, fontWeight: 500, color: t.muted }}>{a.label}</span>\n                    </motion.div>\n                  </Link>\n                );\n              })}\n            </div>\n          </motion.div>\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/content-studio/page.tsx":"\"use client\";\nimport { useState, useRef } from \"react\";\nimport { useMutation } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { useCreditsStore } from \"../../../store/credits.store\";\nimport { Film, Sparkles, Download, Loader2, Zap, AlertTriangle, Play, Clock, Star } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\nimport Link from \"next/link\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\n\n// Real product images from Unsplash for visual examples\nconst TEMPLATE_EXAMPLES = {\n  product_showcase: \"https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=300&h=180&fit=crop\",\n  flash_sale:       \"https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?w=300&h=180&fit=crop\",\n  brand_story:      \"https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=300&h=180&fit=crop\",\n  new_arrival:      \"https://images.unsplash.com/photo-1491553895911-0055eca6402d?w=300&h=180&fit=crop\",\n  testimonial:      \"https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?w=300&h=180&fit=crop&crop=face\",\n  tiktok_script:    \"https://images.unsplash.com/photo-1611162616475-46b635cb6868?w=300&h=180&fit=crop\",\n};\n\nconst TEMPLATES = [\n  { id:\"product_showcase\", label:\"Product Showcase\", desc:\"Cinematic 10-sec product reveal\",  credits:20, badge:\"Popular\",  color:\"#8B5CF6\" },\n  { id:\"flash_sale\",       label:\"Flash Sale\",       desc:\"High-energy countdown ad\",          credits:20, badge:\"Converts\", color:\"#EF4444\" },\n  { id:\"brand_story\",      label:\"Brand Story\",      desc:\"30-sec brand introduction film\",    credits:50, badge:\"Premium\",  color:\"#F59E0B\" },\n  { id:\"new_arrival\",      label:\"New Arrival\",      desc:\"Hype drop announcement\",            credits:20, badge:null,      color:\"#10B981\" },\n  { id:\"testimonial\",      label:\"Review Card\",      desc:\"Customer review animation\",         credits:20, badge:null,      color:\"#06B6D4\" },\n  { id:\"tiktok_script\",    label:\"TikTok Script\",    desc:\"KIRO writes the viral script\",      credits:3,  badge:\"Fast\",    color:\"#EC4899\" },\n];\n\nconst MODES = [\n  { id:\"fast\",    label:\"Fast\",    sub:\"8 seconds\",  time:\"~15s\", credits:20  },\n  { id:\"hd\",      label:\"HD\",      sub:\"15 seconds\", time:\"~45s\", credits:50  },\n  { id:\"premium\", label:\"Premium\", sub:\"30 seconds\", time:\"~2min\",credits:100 },\n];\n\n// Example TikTok scripts shown as inspiration\nconst EXAMPLE_SCRIPTS = [\n  { product:\"Brazilian Hair Bundle\",  hook:\"POV: You found hair that actually lasts\",        duration:\"0:28\" },\n  { product:\"LED Face Mask\",          hook:\"I tried this for 7 days. The results shocked me\", duration:\"0:34\" },\n  { product:\"Wireless Earbuds\",       hook:\"These are not $500 earbuds. They cost $30.\",      duration:\"0:22\" },\n];\n\nexport default function ContentStudioPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card:   isDark ? \"#0F0C1E\" : \"#fff\",\n    card2:  isDark ? \"#181230\" : \"#F8F7FF\",\n    border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(107,53,232,0.1)\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\" : \"rgba(19,13,46,0.55)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(107,53,232,0.04)\",\n  };\n\n  const storeId = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const { balance, deduct } = useCreditsStore();\n  const [template, setTemplate] = useState(\"product_showcase\");\n  const [mode, setMode]         = useState(\"fast\");\n  const [productName, setProductName] = useState(\"\");\n  const [hook, setHook]         = useState(\"\");\n  const [result, setResult]     = useState<{url:string;type:\"video\"|\"script\"}|null>(null);\n  const [activeTab, setActiveTab] = useState<\"video\"|\"script\">(\"video\");\n\n  const isTiktok  = template === \"tiktok_script\";\n  const credits   = isTiktok ? 3 : MODES.find(m => m.id === mode)!.credits;\n  const canAfford = balance >= credits;\n  const selectedTpl = TEMPLATES.find(t => t.id === template)!;\n\n  const genMut = useMutation({\n    mutationFn: async () => {\n      if (!canAfford) throw new Error(\"credits\");\n      deduct(credits);\n      if (isTiktok) {\n        const prompt = `Write a viral TikTok script for: ${productName}. Hook: ${hook || \"surprise the viewer\"}. 30-60 seconds. Make it highly engaging.`;\n        const res = await api.post(\"/kai/smart-chat\", { message: prompt, storeId });\n        return { url: res.data.data?.reply || res.data.reply || \"\", type:\"script\" as const };\n      }\n      const res = await api.post(\"/super/video/generate\", { template, mode, productName, hook, storeId });\n      return { url: res.data.data?.url || res.data.url || \"\", type:\"video\" as const };\n    },\n    onSuccess: (r) => { setResult(r); toast.success(isTiktok ? \"Script written!\" : \"Video generated!\"); },\n    onError: (e:any) => {\n      if (e.message === \"credits\") { toast.error(\"Not enough credits\"); return; }\n      if (isTiktok) toast.error(\"Backend offline\");\n      else toast(\"Add KLING_API_KEY to Render to enable video generation\", { icon:\"⚙️\", duration:6000 });\n    },\n  });\n\n  const inp = {\n    width:\"100%\", padding:\"11px 14px\", borderRadius:12,\n    border:`1px solid ${t.border}`, background:t.faint,\n    color:t.text, fontSize:14, outline:\"none\", fontFamily:\"inherit\",\n  } as const;\n\n  return (\n    <div style={{ maxWidth:1100, margin:\"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{ display:\"flex\", alignItems:\"flex-start\", justifyContent:\"space-between\", gap:16, marginBottom:28, flexWrap:\"wrap\" }}>\n        <div>\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:6 }}>\n            <h1 style={{ fontSize:22, fontWeight:900, letterSpacing:\"-0.8px\", color:t.text }}>Content Studio</h1>\n            <span style={{ fontSize:10, fontWeight:700, letterSpacing:\"0.08em\", padding:\"3px 8px\", borderRadius:99, background:\"rgba(107,53,232,0.12)\", color:V.v300, border:\"1px solid rgba(107,53,232,0.2)\", textTransform:\"uppercase\" }}>AI Powered</span>\n          </div>\n          <p style={{ fontSize:13, color:t.muted }}>Generate product videos, TikTok scripts, and ad creatives in seconds</p>\n        </div>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"8px 14px\", borderRadius:12, background:\"rgba(107,53,232,0.08)\", border:\"1px solid rgba(107,53,232,0.18)\" }}>\n          <Zap size={13} color={V.v400}/>\n          <span style={{ fontSize:13, fontWeight:700, color:V.v300 }}>{balance.toLocaleString()} credits</span>\n        </div>\n      </motion.div>\n\n      <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:20, alignItems:\"start\" }}>\n\n        {/* LEFT PANEL */}\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:16 }}>\n\n          {/* Template picker - visual cards */}\n          <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.06}}\n            style={{ borderRadius:18, overflow:\"hidden\", border:`1px solid ${t.border}`, background:t.card }}>\n            <div style={{ padding:\"14px 16px 10px\", borderBottom:`1px solid ${t.border}` }}>\n              <p style={{ fontSize:11, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted }}>Choose Format</p>\n            </div>\n            <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr 1fr\", gap:1, background:t.border }}>\n              {TEMPLATES.map((tpl,i) => {\n                const isActive = template === tpl.id;\n                const imgUrl = TEMPLATE_EXAMPLES[tpl.id as keyof typeof TEMPLATE_EXAMPLES];\n                return (\n                  <button key={tpl.id} onClick={() => setTemplate(tpl.id)}\n                    style={{ position:\"relative\", display:\"flex\", flexDirection:\"column\", padding:0, border:\"none\", cursor:\"pointer\", background:isActive?\"rgba(107,53,232,0.12)\":t.card, outline:\"none\" }}>\n                    {/* Video thumbnail */}\n                    <div style={{ position:\"relative\", width:\"100%\", aspectRatio:\"16/9\", overflow:\"hidden\", background:\"#000\" }}>\n                      <img src={imgUrl} alt={tpl.label} style={{ width:\"100%\", height:\"100%\", objectFit:\"cover\", opacity:isActive?1:0.65, transition:\"opacity 0.2s\" }}\n                        onError={e => {(e.target as HTMLImageElement).style.display = \"none\";}}/>\n                      {/* Play overlay */}\n                      <div style={{ position:\"absolute\", inset:0, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                        <div style={{ width:28, height:28, borderRadius:\"50%\", background:\"rgba(0,0,0,0.5)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", backdropFilter:\"blur(4px)\" }}>\n                          <Play size={11} color=\"white\" style={{ marginLeft:1 }}/>\n                        </div>\n                      </div>\n                      {tpl.badge && (\n                        <div style={{ position:\"absolute\", top:5, right:5, fontSize:8, fontWeight:700, padding:\"2px 6px\", borderRadius:99, background:tpl.color, color:\"#fff\", letterSpacing:\"0.05em\" }}>\n                          {tpl.badge}\n                        </div>\n                      )}\n                      {isActive && <div style={{ position:\"absolute\", inset:0, border:`2px solid ${V.v400}`, borderRadius:0 }}/>}\n                    </div>\n                    <div style={{ padding:\"8px 10px 10px\", textAlign:\"left\", width:\"100%\" }}>\n                      <p style={{ fontSize:11, fontWeight:700, color:isActive?V.v200:t.text, marginBottom:2 }}>{tpl.label}</p>\n                      <p style={{ fontSize:9.5, color:t.muted, lineHeight:1.4 }}>{tpl.desc}</p>\n                      <p style={{ fontSize:9, fontWeight:700, color:tpl.color, marginTop:4 }}>{tpl.credits} credits</p>\n                    </div>\n                  </button>\n                );\n              })}\n            </div>\n          </motion.div>\n\n          {/* Quality mode - only for video */}\n          {!isTiktok && (\n            <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.1}}\n              style={{ borderRadius:18, border:`1px solid ${t.border}`, background:t.card, overflow:\"hidden\" }}>\n              <div style={{ padding:\"14px 16px 10px\", borderBottom:`1px solid ${t.border}` }}>\n                <p style={{ fontSize:11, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted }}>Video Quality</p>\n              </div>\n              <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr 1fr\", gap:0 }}>\n                {MODES.map((m,i) => {\n                  const isActive = mode === m.id;\n                  return (\n                    <button key={m.id} onClick={() => setMode(m.id)}\n                      style={{ padding:\"14px 12px\", border:\"none\", borderRight:i<2?`1px solid ${t.border}`:\"none\", cursor:\"pointer\", background:isActive?\"rgba(107,53,232,0.1)\":t.card, outline:\"none\", textAlign:\"center\", transition:\"background 0.15s\" }}>\n                      <div style={{ fontSize:11, fontWeight:800, color:isActive?V.v300:t.text, marginBottom:3 }}>{m.label}</div>\n                      <div style={{ fontSize:10, color:t.muted, marginBottom:4 }}>{m.sub}</div>\n                      <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:4 }}>\n                        <Clock size={9} color={t.muted}/>\n                        <span style={{ fontSize:9, color:t.muted }}>{m.time}</span>\n                        <span style={{ fontSize:9, fontWeight:700, color:isActive?V.v400:t.muted }}>{m.credits}cr</span>\n                      </div>\n                    </button>\n                  );\n                })}\n              </div>\n            </motion.div>\n          )}\n\n          {/* Product details */}\n          <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.14}}\n            style={{ borderRadius:18, border:`1px solid ${t.border}`, background:t.card, padding:16 }}>\n            <p style={{ fontSize:11, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted, marginBottom:12 }}>Product Details</p>\n            <div style={{ display:\"flex\", flexDirection:\"column\", gap:10 }}>\n              <input value={productName} onChange={e=>setProductName(e.target.value)}\n                placeholder={isTiktok ? \"What product is this script for?\" : \"Product name\"}\n                style={inp}/>\n              <input value={hook} onChange={e=>setHook(e.target.value)}\n                placeholder={isTiktok ? \"Angle or hook (optional)\" : \"Key message or offer\"}\n                style={inp}/>\n            </div>\n          </motion.div>\n\n          {/* Credits warning */}\n          {!canAfford && (\n            <div style={{ display:\"flex\", alignItems:\"center\", gap:10, padding:\"12px 14px\", borderRadius:12, background:\"rgba(239,68,68,0.08)\", border:\"1px solid rgba(239,68,68,0.2)\" }}>\n              <AlertTriangle size={14} color=\"#EF4444\"/>\n              <p style={{ fontSize:12, color:\"#EF4444\", flex:1 }}>You need {credits} credits.</p>\n              <Link href=\"/dashboard/billing\" style={{ fontSize:12, fontWeight:700, color:\"#EF4444\" }}>Top up</Link>\n            </div>\n          )}\n\n          {/* Generate button */}\n          <motion.button whileTap={{scale:0.97}} onClick={() => genMut.mutate()}\n            disabled={!productName || genMut.isPending || !canAfford}\n            style={{ width:\"100%\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:10, padding:\"14px\", borderRadius:14, border:\"none\", cursor:productName&&canAfford?\"pointer\":\"not-allowed\", fontFamily:\"inherit\", fontSize:14, fontWeight:800, color:\"#fff\", background:productName&&canAfford?\"linear-gradient(135deg,#6B35E8,#3D1C8A)\":\"rgba(255,255,255,0.06)\", opacity:(!productName||!canAfford)&&!genMut.isPending?0.5:1, transition:\"all 0.15s\" }}>\n            {genMut.isPending\n              ? <><Loader2 size={16} style={{animation:\"spin 1s linear infinite\"}}/> Generating... ({credits} credits)</>\n              : isTiktok\n                ? <><Sparkles size={16}/> Write TikTok Script ({credits} credits)</>\n                : <><Film size={16}/> Generate Video ({credits} credits)</>\n            }\n          </motion.button>\n        </div>\n\n        {/* RIGHT PANEL */}\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:16 }}>\n\n          {/* Output panel */}\n          <motion.div initial={{opacity:0,x:20}} animate={{opacity:1,x:0}} transition={{delay:0.1}}\n            style={{ borderRadius:18, border:`1px solid ${t.border}`, background:t.card, overflow:\"hidden\", minHeight:320 }}>\n            <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", padding:\"14px 16px\", borderBottom:`1px solid ${t.border}` }}>\n              <p style={{ fontSize:11, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted }}>Preview</p>\n              {result?.type===\"video\" && result.url && (\n                <a href={result.url} download target=\"_blank\" style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"6px 12px\", borderRadius:10, background:\"rgba(107,53,232,0.1)\", color:V.v300, textDecoration:\"none\", fontSize:12, fontWeight:600 }}>\n                  <Download size={11}/> Download\n                </a>\n              )}\n            </div>\n            <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", padding:24, minHeight:260 }}>\n              <AnimatePresence mode=\"wait\">\n                {genMut.isPending && (\n                  <motion.div key=\"loading\" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} style={{textAlign:\"center\"}}>\n                    <motion.div animate={{rotate:360}} transition={{duration:2,repeat:Infinity,ease:\"linear\"}}\n                      style={{width:60,height:60,borderRadius:18,background:\"linear-gradient(135deg,#6B35E8,#3D1C8A)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",margin:\"0 auto 20px\",boxShadow:\"0 12px 36px rgba(107,53,232,0.4)\"}}>\n                      {isTiktok?<Sparkles size={26} color=\"white\"/>:<Film size={26} color=\"white\"/>}\n                    </motion.div>\n                    <p style={{fontSize:14,fontWeight:700,color:t.text,marginBottom:6}}>{isTiktok?\"Writing your script...\":\"Rendering your video...\"}</p>\n                    <p style={{fontSize:12,color:t.muted}}>This takes {isTiktok?\"5-10\":\"15-120\"} seconds</p>\n                  </motion.div>\n                )}\n                {!genMut.isPending && result && (\n                  <motion.div key=\"result\" initial={{opacity:0,scale:0.96}} animate={{opacity:1,scale:1}} style={{width:\"100%\"}}>\n                    {result.type===\"video\" && result.url\n                      ? <video src={result.url} controls style={{width:\"100%\",borderRadius:12,maxHeight:260,background:\"#000\"}}/>\n                      : <div style={{padding:16,borderRadius:14,background:t.faint,border:`1px solid ${t.border}`,fontSize:13,lineHeight:1.7,color:t.text,whiteSpace:\"pre-wrap\",maxHeight:280,overflowY:\"auto\"}}>{result.url}</div>\n                    }\n                  </motion.div>\n                )}\n                {!genMut.isPending && !result && (\n                  <motion.div key=\"empty\" initial={{opacity:0}} animate={{opacity:1}} style={{textAlign:\"center\",padding:\"0 20px\"}}>\n                    <div style={{fontSize:48,marginBottom:16}}>{isTiktok?\"📱\":\"🎬\"}</div>\n                    <p style={{fontSize:14,fontWeight:600,color:t.muted,marginBottom:8}}>{isTiktok?\"Your script appears here\":\"Your video appears here\"}</p>\n                    <p style={{fontSize:12,color:t.muted,opacity:0.7}}>Choose a format, fill in your product, and click generate</p>\n                  </motion.div>\n                )}\n              </AnimatePresence>\n            </div>\n          </motion.div>\n\n          {/* Example scripts for inspiration */}\n          {isTiktok && (\n            <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.2}}\n              style={{borderRadius:18,border:`1px solid ${t.border}`,background:t.card,overflow:\"hidden\"}}>\n              <div style={{padding:\"14px 16px 10px\",borderBottom:`1px solid ${t.border}`}}>\n                <p style={{fontSize:11,fontWeight:700,textTransform:\"uppercase\",letterSpacing:\"0.1em\",color:t.muted}}>Script Examples</p>\n              </div>\n              <div style={{padding:\"12px 16px\",display:\"flex\",flexDirection:\"column\",gap:10}}>\n                {EXAMPLE_SCRIPTS.map((ex,i) => (\n                  <div key={i} style={{padding:\"12px\",borderRadius:12,background:t.faint,border:`1px solid ${t.border}`}}>\n                    <div style={{display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",marginBottom:5}}>\n                      <p style={{fontSize:12,fontWeight:700,color:t.text}}>{ex.product}</p>\n                      <span style={{fontSize:10,color:t.muted,display:\"flex\",alignItems:\"center\",gap:4}}><Clock size={9}/>{ex.duration}</span>\n                    </div>\n                    <p style={{fontSize:12,color:t.muted,fontStyle:\"italic\"}}>\"{ex.hook}\"</p>\n                  </div>\n                ))}\n              </div>\n            </motion.div>\n          )}\n\n          {/* Stats row */}\n          {!isTiktok && (\n            <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.2}}\n              style={{display:\"grid\",gridTemplateColumns:\"1fr 1fr 1fr\",gap:1,borderRadius:18,overflow:\"hidden\",border:`1px solid ${t.border}`,background:t.border}}>\n              {[{n:\"10s\",l:\"Average generation\"},{n:\"4K\",l:\"Maximum resolution\"},{n:\"16+\",l:\"Video styles\"}].map((s,i)=>(\n                <div key={i} style={{padding:\"14px\",background:t.card,textAlign:\"center\"}}>\n                  <p style={{fontSize:18,fontWeight:900,color:t.text,letterSpacing:\"-0.5px\"}}>{s.n}</p>\n                  <p style={{fontSize:10,color:t.muted,marginTop:2}}>{s.l}</p>\n                </div>\n              ))}\n            </motion.div>\n          )}\n\n          {/* Tips */}\n          <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.25}}\n            style={{borderRadius:18,border:\"1px solid rgba(107,53,232,0.15)\",background:\"rgba(107,53,232,0.04)\",padding:16}}>\n            <div style={{display:\"flex\",alignItems:\"center\",gap:8,marginBottom:10}}>\n              <Zap size={13} color={V.v400}/>\n              <p style={{fontSize:11,fontWeight:700,color:V.v300}}>KIRO tips for better results</p>\n            </div>\n            <div style={{display:\"flex\",flexDirection:\"column\",gap:6}}>\n              {[\"Be specific with product name — 'Brazilian Hair Bundle 18 inch' converts 3x better than just 'hair'\",isTiktok?\"Include the hook angle — 'survival' or 'transformation' angles outperform generic scripts\":\"Provide a clear message — 'launches April 30' or '50% off today only' works best\"].map((tip,i) => (\n                <div key={i} style={{display:\"flex\",alignItems:\"start\",gap:8}}>\n                  <span style={{fontSize:10,color:V.v400,flexShrink:0,marginTop:2}}>→</span>\n                  <p style={{fontSize:11,color:\"rgba(255,255,255,0.5)\",lineHeight:1.5}}>{tip}</p>\n                </div>\n              ))}\n            </div>\n          </motion.div>\n        </div>\n      </div>\n\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/src/app/dashboard/image-studio/page.tsx":"\"use client\";\nimport { useState, useRef } from \"react\";\nimport { useMutation } from \"@tanstack/react-query\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useTheme } from \"../../../components/layout/DashboardLayout\";\nimport { useAuthStore } from \"../../../store/auth.store\";\nimport { api } from \"../../../lib/api\";\nimport { useCreditsStore, CREDIT_COSTS } from \"../../../store/credits.store\";\nimport { Upload, Wand2, Download, Copy, Loader2, X, Check, Zap, Image as ImageIcon, AlertTriangle, Sparkles } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\nimport Link from \"next/link\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\n\n// Before/after examples from Unsplash\nconst TOOL_EXAMPLES = {\n  remove_bg:   {\n    before: \"https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=200&h=200&fit=crop\",\n    after:  \"https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=200&h=200&fit=crop&sat=-100\",\n    label:  \"Clean white background\"\n  },\n  lifestyle:   {\n    before: \"https://images.unsplash.com/photo-1491553895911-0055eca6402d?w=200&h=200&fit=crop\",\n    after:  \"https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=200&h=200&fit=crop\",\n    label:  \"Product in real setting\"\n  },\n  enhance:     {\n    before: \"https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=200&h=200&fit=crop&blur=2\",\n    after:  \"https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=200&h=200&fit=crop\",\n    label:  \"Sharp professional quality\"\n  },\n  ad_creative: {\n    before: \"https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?w=200&h=200&fit=crop\",\n    after:  \"https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?w=200&h=200&fit=crop&bri=30\",\n    label:  \"Ready-to-post ad\"\n  },\n};\n\nconst TOOLS = [\n  { id:\"remove_bg\",   icon:\"✂️\", label:\"Remove Background\", desc:\"Perfect white or transparent BG\", credits:5  },\n  { id:\"lifestyle\",   icon:\"🌟\", label:\"Lifestyle Scene\",   desc:\"Product in a real-world setting\",  credits:15 },\n  { id:\"enhance\",     icon:\"✨\", label:\"Enhance Photo\",     desc:\"Sharpen and improve lighting\",      credits:5  },\n  { id:\"ad_creative\", icon:\"📣\", label:\"Ad Creative\",       desc:\"Social-ready ad with text\",         credits:10 },\n];\n\nconst BACKGROUNDS = [\n  { id:\"studio\",   emoji:\"⬜\", label:\"Studio\"    },\n  { id:\"bedroom\",  emoji:\"🛏️\", label:\"Bedroom\"  },\n  { id:\"kitchen\",  emoji:\"🍳\", label:\"Kitchen\"   },\n  { id:\"outdoor\",  emoji:\"🌿\", label:\"Outdoor\"   },\n  { id:\"luxury\",   emoji:\"✨\", label:\"Luxury\"    },\n  { id:\"flat_lay\", emoji:\"📐\", label:\"Flat Lay\"  },\n];\n\nexport default function ImageStudioPage() {\n  const { theme } = useTheme();\n  const isDark = theme === \"dark\";\n  const t = {\n    card:   isDark ? \"#0F0C1E\" : \"#fff\",\n    border: isDark ? \"rgba(255,255,255,0.06)\" : \"rgba(107,53,232,0.1)\",\n    text:   isDark ? \"#F0ECFF\" : \"#130D2E\",\n    muted:  isDark ? \"rgba(240,236,255,0.5)\" : \"rgba(19,13,46,0.55)\",\n    faint:  isDark ? \"rgba(255,255,255,0.03)\" : \"rgba(107,53,232,0.04)\",\n  };\n  const storeId  = useAuthStore(s => s.user?.stores?.[0]?.id);\n  const { balance, deduct } = useCreditsStore();\n\n  const [tool,        setTool]        = useState(\"remove_bg\");\n  const [imageUrl,    setImageUrl]    = useState(\"\");\n  const [bgStyle,     setBgStyle]     = useState(\"studio\");\n  const [productName, setProductName] = useState(\"\");\n  const [result,      setResult]      = useState<string|null>(null);\n  const [uploading,   setUploading]   = useState(false);\n  const [copied,      setCopied]      = useState(false);\n  const [showBefore,  setShowBefore]  = useState(false);\n  const fileRef = useRef<HTMLInputElement>(null);\n\n  const selectedTool = TOOLS.find(t => t.id === tool)!;\n  const canAfford    = balance >= selectedTool.credits;\n  const example      = TOOL_EXAMPLES[tool as keyof typeof TOOL_EXAMPLES];\n\n  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {\n    const file = e.target.files?.[0];\n    if (!file) return;\n    setUploading(true);\n    try {\n      const fd = new FormData(); fd.append(\"file\", file); fd.append(\"upload_preset\", \"dropos_products\");\n      const cloudName = process.env.NEXT_PUBLIC_CLOUDINARY_CLOUD_NAME || \"demo\";\n      const res  = await fetch(`https://api.cloudinary.com/v1_1/${cloudName}/image/upload`, { method:\"POST\", body:fd });\n      const data = await res.json();\n      if (data.secure_url) { setImageUrl(data.secure_url); setResult(null); }\n      else toast.error(\"Upload failed\");\n    } catch { toast.error(\"Upload failed\"); }\n    finally { setUploading(false); e.target.value = \"\"; }\n  };\n\n  const processMut = useMutation({\n    mutationFn: async () => {\n      if (!canAfford) throw new Error(\"credits\");\n      deduct(selectedTool.credits);\n      const endpoint = tool === \"remove_bg\" ? \"/super/images/remove-bg\"\n        : tool === \"lifestyle\" ? \"/super/images/lifestyle\"\n        : tool === \"enhance\"   ? \"/super/images/enhance\"\n        : \"/super/images/ad-creative\";\n      const body = { imageUrl, storeId, backgroundStyle: bgStyle, productName };\n      const r = await api.post(endpoint, body);\n      return r.data.data?.url || r.data.url;\n    },\n    onSuccess: (url) => { setResult(url); toast.success(\"Image ready!\"); },\n    onError: (e:any) => {\n      if (e.message === \"credits\") { toast.error(\"Not enough credits\"); return; }\n      toast(\"Add FAL_AI_KEY to Render to enable AI generation\", { icon:\"⚙️\", duration:6000 });\n    },\n  });\n\n  const inp = { width:\"100%\", padding:\"11px 14px\", borderRadius:12, border:`1px solid ${t.border}`, background:t.faint, color:t.text, fontSize:13, outline:\"none\", fontFamily:\"inherit\" } as const;\n\n  return (\n    <div style={{ maxWidth:1000, margin:\"0 auto\" }}>\n      {/* Header */}\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{ display:\"flex\", alignItems:\"flex-start\", justifyContent:\"space-between\", marginBottom:24, flexWrap:\"wrap\", gap:12 }}>\n        <div>\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:6 }}>\n            <h1 style={{ fontSize:22, fontWeight:900, letterSpacing:\"-0.8px\", color:t.text }}>Image Studio</h1>\n            <span style={{ fontSize:10, fontWeight:700, padding:\"3px 8px\", borderRadius:99, background:\"rgba(107,53,232,0.12)\", color:V.v300, border:\"1px solid rgba(107,53,232,0.2)\", textTransform:\"uppercase\", letterSpacing:\"0.06em\" }}>Fal.ai</span>\n          </div>\n          <p style={{ fontSize:13, color:t.muted }}>Professional product photos without a photographer</p>\n        </div>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"8px 14px\", borderRadius:12, background:\"rgba(107,53,232,0.08)\", border:\"1px solid rgba(107,53,232,0.18)\" }}>\n          <Zap size={13} color={V.v400}/><span style={{ fontSize:13, fontWeight:700, color:V.v300 }}>{balance.toLocaleString()} credits</span>\n        </div>\n      </motion.div>\n\n      <div style={{ display:\"grid\", gridTemplateColumns:\"300px 1fr\", gap:16, alignItems:\"start\" }}>\n\n        {/* LEFT - Controls */}\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:14 }}>\n\n          {/* Tool picker with visual examples */}\n          <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.06}}\n            style={{ borderRadius:18, border:`1px solid ${t.border}`, background:t.card, overflow:\"hidden\" }}>\n            <div style={{ padding:\"14px 16px 10px\", borderBottom:`1px solid ${t.border}` }}>\n              <p style={{ fontSize:11, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted }}>Choose Tool</p>\n            </div>\n            <div style={{ padding:\"8px\" }}>\n              {TOOLS.map(tl => {\n                const isActive = tool === tl.id;\n                return (\n                  <button key={tl.id} onClick={() => { setTool(tl.id); setResult(null); }}\n                    style={{ width:\"100%\", display:\"flex\", alignItems:\"center\", gap:12, padding:\"10px 12px\", borderRadius:12, border:`1px solid ${isActive?\"rgba(107,53,232,0.3)\":\"transparent\"}`, background:isActive?\"rgba(107,53,232,0.1)\":\"transparent\", cursor:\"pointer\", marginBottom:4, transition:\"all 0.15s\" }}>\n                    <span style={{ fontSize:18, flexShrink:0 }}>{tl.icon}</span>\n                    <div style={{ flex:1, textAlign:\"left\" }}>\n                      <p style={{ fontSize:12, fontWeight:700, color:isActive?V.v200:t.text }}>{tl.label}</p>\n                      <p style={{ fontSize:10, color:t.muted }}>{tl.desc}</p>\n                    </div>\n                    <span style={{ fontSize:9, fontWeight:700, padding:\"2px 7px\", borderRadius:99, background:\"rgba(107,53,232,0.1)\", color:V.v400 }}>{tl.credits}cr</span>\n                    {isActive && <Check size={12} color={V.v400}/>}\n                  </button>\n                );\n              })}\n            </div>\n          </motion.div>\n\n          {/* Background picker for lifestyle */}\n          {tool === \"lifestyle\" && (\n            <motion.div initial={{opacity:0,y:8}} animate={{opacity:1,y:0}}\n              style={{ borderRadius:18, border:`1px solid ${t.border}`, background:t.card, padding:16 }}>\n              <p style={{ fontSize:11, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted, marginBottom:12 }}>Background</p>\n              <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr 1fr\", gap:8 }}>\n                {BACKGROUNDS.map(bg => (\n                  <button key={bg.id} onClick={() => setBgStyle(bg.id)}\n                    style={{ padding:\"10px 6px\", borderRadius:10, border:`1px solid ${bgStyle===bg.id?\"rgba(107,53,232,0.4)\":t.border}`, background:bgStyle===bg.id?\"rgba(107,53,232,0.12)\":t.faint, cursor:\"pointer\", display:\"flex\", flexDirection:\"column\", alignItems:\"center\", gap:4 }}>\n                    <span style={{ fontSize:18 }}>{bg.emoji}</span>\n                    <span style={{ fontSize:9, fontWeight:600, color:bgStyle===bg.id?V.v300:t.muted }}>{bg.label}</span>\n                  </button>\n                ))}\n              </div>\n            </motion.div>\n          )}\n\n          {/* Product name for ad creative */}\n          {tool === \"ad_creative\" && (\n            <motion.div initial={{opacity:0,y:8}} animate={{opacity:1,y:0}}\n              style={{ borderRadius:18, border:`1px solid ${t.border}`, background:t.card, padding:16 }}>\n              <p style={{ fontSize:11, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted, marginBottom:10 }}>Ad Text</p>\n              <input value={productName} onChange={e=>setProductName(e.target.value)} placeholder=\"Product name for the ad\" style={inp}/>\n            </motion.div>\n          )}\n\n          {/* Generate button */}\n          {!canAfford && (\n            <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"10px 14px\", borderRadius:12, background:\"rgba(239,68,68,0.08)\", border:\"1px solid rgba(239,68,68,0.2)\" }}>\n              <AlertTriangle size={13} color=\"#EF4444\"/>\n              <p style={{ fontSize:12, color:\"#EF4444\", flex:1 }}>Need {selectedTool.credits} credits</p>\n              <Link href=\"/dashboard/billing\" style={{ fontSize:12, fontWeight:700, color:\"#EF4444\" }}>Top up</Link>\n            </div>\n          )}\n          <motion.button whileTap={{scale:0.97}} onClick={() => processMut.mutate()}\n            disabled={!imageUrl || processMut.isPending || !canAfford}\n            style={{ width:\"100%\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:8, padding:\"13px\", borderRadius:14, border:\"none\", cursor:imageUrl&&canAfford?\"pointer\":\"not-allowed\", fontFamily:\"inherit\", fontSize:13, fontWeight:800, color:\"#fff\", background:imageUrl&&canAfford?\"linear-gradient(135deg,#6B35E8,#3D1C8A)\":\"rgba(255,255,255,0.06)\", opacity:(!imageUrl||!canAfford)&&!processMut.isPending?0.5:1, transition:\"all 0.15s\" }}>\n            {processMut.isPending ? <><Loader2 size={14} style={{animation:\"spin 1s linear infinite\"}}/> Processing...</> : <><Wand2 size={14}/> Generate ({selectedTool.credits} credits)</>}\n          </motion.button>\n        </div>\n\n        {/* RIGHT - Upload + Result */}\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:14 }}>\n\n          {/* Upload area */}\n          {!imageUrl ? (\n            <motion.div initial={{opacity:0,x:16}} animate={{opacity:1,x:0}} transition={{delay:0.08}}\n              onClick={() => fileRef.current?.click()}\n              style={{ borderRadius:18, border:`2px dashed ${t.border}`, background:t.faint, padding:32, display:\"flex\", flexDirection:\"column\", alignItems:\"center\", gap:12, cursor:\"pointer\", transition:\"all 0.2s\", minHeight:200 }}>\n              {uploading\n                ? <Loader2 size={32} style={{color:V.v400,animation:\"spin 1s linear infinite\"}}/>\n                : <Upload size={32} style={{color:t.muted}}/>}\n              <div style={{ textAlign:\"center\" }}>\n                <p style={{ fontSize:15, fontWeight:700, color:t.text, marginBottom:4 }}>{uploading?\"Uploading...\":\"Upload your product photo\"}</p>\n                <p style={{ fontSize:12, color:t.muted }}>JPG or PNG, max 10MB</p>\n              </div>\n              {/* Example images grid */}\n              {!uploading && (\n                <div style={{ display:\"flex\", gap:8, marginTop:8, flexWrap:\"wrap\", justifyContent:\"center\" }}>\n                  {[\"photo-1523275335684-37898b6baf30\",\"photo-1491553895911-0055eca6402d\",\"photo-1584308666744-24d5c474f2ae\"].map(id => (\n                    <img key={id} src={`https://images.unsplash.com/${id}?w=60&h=60&fit=crop`} alt=\"example\"\n                      style={{ width:52, height:52, borderRadius:10, objectFit:\"cover\", opacity:0.5, border:`1px solid ${t.border}` }}\n                      onError={e=>{(e.target as HTMLImageElement).style.display=\"none\";}}/>\n                  ))}\n                  <div style={{ width:52, height:52, borderRadius:10, background:\"rgba(107,53,232,0.1)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontSize:10, color:V.v400, fontWeight:700 }}>+more</div>\n                </div>\n              )}\n            </motion.div>\n          ) : (\n            <motion.div initial={{opacity:0,scale:0.96}} animate={{opacity:1,scale:1}}\n              style={{ borderRadius:18, border:`1px solid ${t.border}`, background:t.card, overflow:\"hidden\" }}>\n              <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", padding:\"12px 16px\", borderBottom:`1px solid ${t.border}` }}>\n                <p style={{ fontSize:11, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted }}>Your Photo</p>\n                <button onClick={() => { setImageUrl(\"\"); setResult(null); }} style={{ width:28, height:28, borderRadius:\"50%\", border:\"none\", background:\"rgba(239,68,68,0.1)\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  <X size={13} color=\"#EF4444\"/>\n                </button>\n              </div>\n              <div style={{ padding:12 }}>\n                <img src={imageUrl} alt=\"uploaded\" style={{ width:\"100%\", maxHeight:200, objectFit:\"contain\", borderRadius:12, background:t.faint }}/>\n              </div>\n            </motion.div>\n          )}\n\n          {/* Result */}\n          <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.14}}\n            style={{ borderRadius:18, border:`1px solid ${t.border}`, background:t.card, overflow:\"hidden\", minHeight:240 }}>\n            <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", padding:\"12px 16px\", borderBottom:`1px solid ${t.border}` }}>\n              <p style={{ fontSize:11, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted }}>Result</p>\n              {result && (\n                <div style={{ display:\"flex\", gap:8 }}>\n                  <button onClick={() => { navigator.clipboard.writeText(result); setCopied(true); setTimeout(()=>setCopied(false),2000); }}\n                    style={{ display:\"flex\", alignItems:\"center\", gap:5, padding:\"5px 10px\", borderRadius:8, border:`1px solid ${t.border}`, background:t.faint, cursor:\"pointer\", fontSize:11, fontWeight:600, color:copied?\"#10B981\":t.muted }}>\n                    {copied?<Check size={10}/>:<Copy size={10}/>} {copied?\"Copied\":\"Copy URL\"}\n                  </button>\n                  <a href={result} download target=\"_blank\"\n                    style={{ display:\"flex\", alignItems:\"center\", gap:5, padding:\"5px 10px\", borderRadius:8, background:\"rgba(107,53,232,0.1)\", color:V.v300, textDecoration:\"none\", fontSize:11, fontWeight:600 }}>\n                    <Download size={10}/> Download\n                  </a>\n                </div>\n              )}\n            </div>\n            <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", padding:20, minHeight:200 }}>\n              <AnimatePresence mode=\"wait\">\n                {processMut.isPending && (\n                  <motion.div key=\"loading\" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} style={{textAlign:\"center\"}}>\n                    <motion.div animate={{rotate:360}} transition={{duration:1.5,repeat:Infinity,ease:\"linear\"}}\n                      style={{width:52,height:52,borderRadius:16,background:\"linear-gradient(135deg,#6B35E8,#3D1C8A)\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",margin:\"0 auto 16px\"}}>\n                      <Wand2 size={24} color=\"white\"/>\n                    </motion.div>\n                    <p style={{fontSize:13,fontWeight:700,color:t.text,marginBottom:4}}>Processing your image...</p>\n                    <p style={{fontSize:11,color:t.muted}}>15-30 seconds</p>\n                  </motion.div>\n                )}\n                {!processMut.isPending && result && (\n                  <motion.div key=\"result\" initial={{opacity:0,scale:0.95}} animate={{opacity:1,scale:1}} style={{width:\"100%\"}}>\n                    <img src={result} alt=\"generated\" style={{width:\"100%\",maxHeight:300,objectFit:\"contain\",borderRadius:12,background:tool===\"remove_bg\"?\"repeating-conic-gradient(rgba(255,255,255,0.05) 0% 25%, transparent 0% 50%) 0 0 / 16px 16px\":t.faint}}/>\n                  </motion.div>\n                )}\n                {!processMut.isPending && !result && (\n                  <motion.div key=\"empty\" initial={{opacity:0}} animate={{opacity:1}} style={{textAlign:\"center\"}}>\n                    <div style={{fontSize:40,marginBottom:12}}>{selectedTool.icon}</div>\n                    <p style={{fontSize:13,color:t.muted}}>{selectedTool.label}</p>\n                    <p style={{fontSize:11,color:t.muted,opacity:0.6,marginTop:4}}>Upload a photo to begin</p>\n                  </motion.div>\n                )}\n              </AnimatePresence>\n            </div>\n          </motion.div>\n\n          {/* Before/after examples */}\n          <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.2}}\n            style={{borderRadius:18,border:`1px solid ${t.border}`,background:t.card,overflow:\"hidden\"}}>\n            <div style={{padding:\"12px 16px 8px\",borderBottom:`1px solid ${t.border}`}}>\n              <p style={{fontSize:11,fontWeight:700,textTransform:\"uppercase\",letterSpacing:\"0.1em\",color:t.muted}}>Example Results</p>\n            </div>\n            <div style={{padding:12,display:\"flex\",gap:10,alignItems:\"center\",justifyContent:\"center\"}}>\n              <div style={{textAlign:\"center\"}}>\n                <img src={example.before} alt=\"before\" style={{width:90,height:90,objectFit:\"cover\",borderRadius:10,border:`1px solid ${t.border}`}} onError={e=>{(e.target as HTMLImageElement).style.display=\"none\";}}/>\n                <p style={{fontSize:9,color:t.muted,marginTop:4}}>Before</p>\n              </div>\n              <span style={{fontSize:18,color:V.v400}}>→</span>\n              <div style={{textAlign:\"center\"}}>\n                <img src={example.after} alt=\"after\" style={{width:90,height:90,objectFit:\"cover\",borderRadius:10,border:`1px solid rgba(107,53,232,0.3)`}} onError={e=>{(e.target as HTMLImageElement).style.display=\"none\";}}/>\n                <p style={{fontSize:9,color:t.muted,marginTop:4}}>After</p>\n              </div>\n              <div style={{flex:1,paddingLeft:8}}>\n                <p style={{fontSize:11,fontWeight:700,color:t.text,marginBottom:4}}>{selectedTool.label}</p>\n                <p style={{fontSize:10,color:t.muted,lineHeight:1.5}}>{example.label}</p>\n              </div>\n            </div>\n          </motion.div>\n        </div>\n      </div>\n\n      <input ref={fileRef} type=\"file\" accept=\"image/*\" style={{display:\"none\"}} onChange={handleUpload}/>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n","frontend/public/favicon.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\">\n  <defs>\n    <linearGradient id=\"bg\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#6B35E8\"/>\n      <stop offset=\"100%\" stop-color=\"#2A0D7A\"/>\n    </linearGradient>\n  </defs>\n  <rect width=\"32\" height=\"32\" rx=\"7\" fill=\"url(#bg)\"/>\n  <path d=\"M18.5 4.5 L11 17 H15.5 L13.5 27.5 L22 15 H17 L19.5 4.5 Z\" fill=\"white\"/>\n</svg>\n","frontend/public/icons/icon.svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\">\n  <defs>\n    <linearGradient id=\"bg\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#6B35E8\"/>\n      <stop offset=\"100%\" stop-color=\"#2A0D7A\"/>\n    </linearGradient>\n    <linearGradient id=\"zap\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#FFFFFF\"/>\n      <stop offset=\"100%\" stop-color=\"#C4B5FD\"/>\n    </linearGradient>\n    <filter id=\"glow\">\n      <feGaussianBlur stdDeviation=\"8\" result=\"blur\"/>\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\n    </filter>\n  </defs>\n  <!-- Rounded square background -->\n  <rect width=\"512\" height=\"512\" rx=\"112\" fill=\"url(#bg)\"/>\n  <!-- Subtle inner glow -->\n  <rect width=\"512\" height=\"512\" rx=\"112\" fill=\"rgba(255,255,255,0.04)\"/>\n  <!-- Zap lightning - clean geometric -->\n  <path d=\"M296 72 L176 272 H252 L216 440 L352 216 H272 L312 72 Z\" fill=\"url(#zap)\" filter=\"url(#glow)\"/>\n</svg>\n"};
let n=0;
for(const [rel,content] of Object.entries(files)){
  const p=rel.replace(/\//g,path.sep);
  fs.mkdirSync(path.dirname(p),{recursive:true});
  fs.writeFileSync(p,content,'utf8');
  console.log('OK',rel.split('/').slice(-2).join('/'));n++;
}
console.log('Written:',n,'files');
try{
  execSync('git add .',{stdio:'inherit'});
  const st=execSync('git status --short',{encoding:'utf8'}).trim();
  if(st){
    execSync('git commit -m "feat: Full backend build - onboarding, milestones, bundles, group buy, referral, reports CSV export, nav-level, contact form, schema updated with all models"',{stdio:'inherit'});
    execSync('git push origin main',{stdio:'inherit'});
    console.log('Pushed. Deploying.');
  }else{console.log('Run: git push origin main');}
}catch(e){console.log('Git:',e.message);}
